  function safeNormalizeCvRoleTitleText(title) {
    var clean = cleanMessageText(title || "");
    if (!clean) {
      return "";
    }
    clean = clean
      .replace(/^[^A-Za-zÀ-ÿ0-9\u0600-\u06FF]+/, "")
      .replace(/^[•▪◦●■□‣\-*＊]+\s*/, "")
      .replace(
        /,\s*(?:\d{1,2}\/\d{4}|\d{4})(?:\s*[-–—]\s*(?:present|current|\d{1,2}\/\d{4}|\d{4}))?.*$/i,
        ""
      )
      .replace(
        /^(?:available from[^-–—:]*[-–—:]\s*)?(?:end-of-studies internship|internship|intern|graduate program)\s*[-–—:]\s*/i,
        ""
      )
      .replace(
        /\s*[-–—/]\s*(?:end-of-studies internship|internship|intern|graduate program)\b(?:\s*[/\-–—]\s*\d+\s*months?)?/i,
        ""
      )
      .replace(/\s*[/\-–—]\s*\d+\s*months?\b/i, "")
      .trim();
    if (isNoisyCvRoleTitleFragment(clean)) {
      return "";
    }
    return clean;
  }

  function hasCvRoleKeyword(text) {
    return /\b(?:analyst|analista|associate|assistant|assistente|manager|director|consultant|consultor|intern|internship|officer|lead|controller|accountant|accounting|auditor|research|banker|specialist|especialista|advisor|vice president|vp|principal|executive|lawyer|graduate|scientist|programmer|engineer|developer|procurement|treasury|compliance|privacy|customer service|call cent(?:re|er)|supply chain|logistics|credit|risk|finance|investment|strategy|trader|trading|private equity|venture capital|order management|business partnerships|alliances|financial specialist|receptionist|administrative|partner|portfolio management|risk management|data analyst|business analyst|data scientist|human resources|treasurer|supervisor|chief)\b|(?:محلل|مدير|محاسب|محاسبة|مدقق|مستشار|أخصائي|اخصائي|مسؤول|منسق|مشرف|تنفيذي|مهندس|مطور|قائد فريق|رئيس قسم|متدرب|خزينة|امتثال|مخاطر|استثمار|تمويل|مالي|موارد بشرية|استقبال|مشتريات|لوجستيات|خدمة العملاء)/i.test(
      cleanMessageText(text || "")
    );
  }

  function hasCoreCvRoleKeyword(text) {
    return /\b(?:analyst|analista|associate|assistant|assistente|manager|director|consultant|consultor|intern|internship|officer|lead|controller|accountant|auditor|banker|specialist|especialista|advisor|vice president|vp|principal|executive|lawyer|graduate|scientist|programmer|engineer|developer|procurement|treasury|compliance|privacy|customer service|call cent(?:re|er)|supply chain|logistics|receptionist|administrative|partner|trader|trading|tutor|teacher|recruiter|recruitment consultant|talent acquisition|treasurer|supervisor|chief)\b|(?:محلل|مدير|محاسب|محاسبة|مدقق|مستشار|أخصائي|اخصائي|مسؤول|منسق|مشرف|تنفيذي|مهندس|مطور|متدرب|خزينة|امتثال|مخاطر|استثمار|تمويل|مالي|موارد بشرية|استقبال|مشتريات|لوجستيات|خدمة العملاء)/i.test(
      cleanMessageText(text || "")
    );
  }

  function looksLikeCvEducationOrObjectiveFragment(text) {
    var clean = cleanMessageText(text || "");
    if (!clean) {
      return false;
    }
    return (
      /^(?:education|academic background|qualifications?|certifications?|career objectives?|objective|objectives|profile summary|professional summary|summary|relevant experience|work experience|skills summary|skills|projects|languages|personal details|area of interest)\b|(?:التعليم|المؤهلات|الشهادات|الهدف الوظيفي|الملخص|الخبرة|المهارات|المشاريع|اللغات|المعلومات الشخصية|مجال الاهتمام)/i.test(
        clean
      ) ||
      /\b(?:bsc|msc|mba|ba|ma|b\.com|m\.com|bachelor(?:'s)?|master(?:'s)?|diploma|coursework|module|modules|dissertation|thesis|dean['’]s list|secondary education|school of|college|university)\b|(?:بكالوريوس|ماجستير|دبلوم|جامعة|كلية|ثانوي)/i.test(
        clean
      ) ||
      (/\b(?:economics|financial economics|international banking|asset pricing)\b/i.test(
        clean
      ) &&
        !hasCoreCvRoleKeyword(clean))
    );
  }

  function deriveCvRoleTitleFromGenericHeading(rawRole, evidenceText) {
    var role = cleanMessageText(rawRole || "").toLowerCase();
    var evidence = cleanMessageText(evidenceText || "").toLowerCase();
    if (!role) {
      return "";
    }
    if (
      /^(?:finance and accounts|accounts and finance|finance\s*&\s*accounts|accounts\s*&\s*finance)$/.test(
        role
      )
    ) {
      if (
        /\b(?:invoice|invoices|financial analysis|balance sheets?|accounting|accounts payable|accounts receivable|reconciliation|budgeting|forecasting)\b/.test(
          evidence
        )
      ) {
        return "Financial Analyst";
      }
      return "Accountant";
    }
    if (/^(?:accounting|accounts?)$/.test(role)) {
      if (
        /\b(?:financial statements?|balance sheets?|cash flow|transactions?|petty cash|ledger|accounting systems?)\b/.test(
          evidence
        )
      ) {
        return "Accountant";
      }
    }
    if (/^(?:trading|trader)$/.test(role)) {
      if (
        /\b(?:foreign exchange|fx|commodities|stocks|equities|futures|options|order flow|portfolio)\b/.test(
          evidence
        )
      ) {
        return "Trader";
      }
    }
    if (/^finance$/.test(role)) {
      if (
        /\b(?:financial statements?|reporting|forecasting|budgeting|reconciliation|treasury)\b/.test(
          evidence
        )
      ) {
        return "Financial Analyst";
      }
    }
    return "";
  }

  function isNoisyCvRoleTitleFragment(text) {
    var clean = cleanMessageText(text || "");
    if (!clean) {
      return true;
    }
    if (
      /^(?:with|and|to|for|from|of|in|on|but|during|before|after)\b/i.test(
        clean
      )
    ) {
      return true;
    }
    if (
      /\b(?:jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\b|(?:يناير|فبراير|مارس|أبريل|ابريل|مايو|يونيو|يوليو|أغسطس|اغسطس|سبتمبر|أكتوبر|اكتوبر|نوفمبر|ديسمبر)/i.test(
        clean
      )
    ) {
      return true;
    }
    if (
      /\b(?:present|current|available from|visible experience|years? of visible experience|recently based around)\b|(?:حتى الآن|حتى الان|إلى الآن|الى الان|حاليا|حالياً|مستمر)/i.test(
        clean
      )
    ) {
      return true;
    }
    if (
      /\b(?:english|arabic|french|german|spanish|hindi|urdu|russian|bulgarian)\b/i.test(
        clean
      ) &&
      !hasCvRoleKeyword(clean)
    ) {
      return true;
    }
    if (looksLikeCvEducationOrObjectiveFragment(clean)) {
      return true;
    }
    if (
      /\b(?:bachelor|master|degree|diploma|certificate|qualification|coursework|thesis|university|school)\b|(?:بكالوريوس|ماجستير|دبلوم|شهادة|مؤهل|جامعة|كلية)/i.test(
        clean
      )
    ) {
      return true;
    }
    if (
      !hasCoreCvRoleKeyword(clean) &&
      /\b(?:finance|investment|research|strategy|analytics?|accounting|banking|economics)\b/i.test(
        clean
      )
    ) {
      return true;
    }
    if (/\b(?: at| for| with| from| and)\s*$/i.test(clean)) {
      return true;
    }
    if (!hasCvRoleKeyword(clean)) {
      return true;
    }
    return false;
  }

  function safeIsWeakCvGenericRoleTitle(title) {
    var clean = safeNormalizeCvRoleTitleText(title || "");
    if (!clean) {
      return true;
    }
    return (
      /^(?:internship|accounting|graduate|objectives?|objective|profile|summary|background|methods for finance|targeted cv draft|relevant role|relevant experience)$/i.test(
        clean
      ) ||
      /\bprofile$/i.test(clean) ||
      /^(?:available from|end-of-studies internship|internship\s*[-–—]\s*\d+\s*months?)\b/i.test(
        clean
      ) ||
      /\b(?:graduate certificate|certificate in|diploma in|applied finance)\b/i.test(
        clean
      ) ||
      /\b(?:university|school|master|bachelor|degree|coursework|education|management school)\b|(?:جامعة|كلية|ماجستير|بكالوريوس|دبلوم|التعليم)\b/i.test(
        clean
      ) ||
      /^(?:i['’]?m|i am)\b/i.test(clean) ||
      /^(?:improved|developed|managed|led|supported|created|prepared|responsible|accomplished|seasoned)\b/i.test(
        clean
      )
    );
  }

  function safeIsRealCvRoleTitle(title) {
    var clean = safeNormalizeCvRoleTitleText(title || "");
    if (!clean || safeIsWeakCvGenericRoleTitle(clean)) {
      return false;
    }
    if (clean.split(/\s+/).length === 1) {
      return /^(?:lawyer|accountant|auditor|analyst|manager|director|consultant|engineer|developer|scientist|programmer|receptionist|assistant|specialist|advisor|banker)$/i.test(
        clean
      );
    }
    return true;
  }

  function safeGetCvRoleFamilyLabel(familyKey) {
    var labels = {
      investment: "Investment",
      credit: "Credit",
      risk_compliance: "Risk / Compliance",
      accounting: "Accounting / Finance",
      technology: "Data / Technology",
      commercial: "Commercial",
      operations: "Operations",
      supply_chain: "Supply Chain",
    };
    return labels[String(familyKey || "")] || "";
  }

  function safeGetStrongCvSkillOverlap(skills) {
    var blocked = {
      sales: true,
      excel: true,
      "project management": true,
      "customer service": true,
    };
    return dedupeList(
      (skills || [])
        .map(function (item) {
          return cleanMessageText(item);
        })
        .filter(function (item) {
          return item && !blocked[item.toLowerCase()];
        })
    );
  }

  function safeDeriveCvRoleTitleFromSignals(families, skills) {
    var familyLabels = dedupeList(
      (families || []).map(safeGetCvRoleFamilyLabel)
    )
      .filter(Boolean)
      .slice(0, 2);
    var strongSkills = safeGetStrongCvSkillOverlap(skills || []);
    if (familyLabels.length >= 2) {
      return familyLabels[0] + " / " + familyLabels[1] + " profile";
    }
    if (familyLabels.length === 1) {
      return familyLabels[0] + " profile";
    }
    if (strongSkills.length >= 2) {
      return strongSkills.slice(0, 2).join(" / ") + " profile";
    }
    return "";
  }

  function safeDeriveJuniorCvAnalystTitle(
    experienceTimeline,
    families,
    skills,
    qualifications,
    rawText
  ) {
    var cvText = String(rawText || "").toLowerCase();
    var currentLevel =
      Number(experienceTimeline[0] && experienceTimeline[0].seniorityLevel) ||
      0;
    var allEarlyCareer =
      (experienceTimeline || []).length &&
      (experienceTimeline || []).every(function (entry) {
        return Number(entry.seniorityLevel || 0) <= 3;
      });

    // Check for repeated senior title terms in the CV text
    // If someone has "Director" or "Manager" etc appearing multiple times, they're not an analyst
    var directorMatches = (cvText.match(/\bdirector\b/gi) || []).length;
    var managerMatches = (cvText.match(/\bmanager\b/gi) || []).length;
    var vpMatches = (cvText.match(/\b(?:vp|vice president)\b/gi) || []).length;
    var headMatches = (cvText.match(/\bhead of\b/gi) || []).length;
    var partnerMatches = (cvText.match(/\bpartner\b/gi) || []).length;
    var mdMatches = (cvText.match(/\bmanaging director\b/gi) || []).length;
    var chiefMatches = (cvText.match(/\b(?:chief|cfo|ceo|cio|coo)\b/gi) || [])
      .length;
    var principalMatches = (cvText.match(/\bprincipal\b/gi) || []).length;

    // If any senior title appears 2+ times, this is likely a senior professional
    var hasSeniorSignals =
      directorMatches >= 2 ||
      managerMatches >= 2 ||
      vpMatches >= 2 ||
      headMatches >= 2 ||
      partnerMatches >= 2 ||
      mdMatches >= 1 ||
      chiefMatches >= 1 ||
      principalMatches >= 2;

    // Also check if the most recent/prominent role is senior
    var hasProminentSeniorTitle =
      /\b(?:director|head of|vice president|vp|managing director|partner|chief|cfo|ceo|cio|coo|principal)\b/i.test(
        cleanMessageText(
          (experienceTimeline[0] && experienceTimeline[0].role) || ""
        )
      );

    if (hasSeniorSignals || hasProminentSeniorTitle) {
      return "";
    }

    var analystSkills = [
      "Financial Analysis",
      "Investment Analysis",
      "Market Research",
      "Research",
      "Power BI",
      "Excel",
      "Stata",
      "SQL",
      "Python",
      "Valuation",
    ];
    var analystSkillHits = analystSkills.filter(function (label) {
      return (skills || []).some(function (skill) {
        return (
          cleanMessageText(skill).toLowerCase() === String(label).toLowerCase()
        );
      });
    }).length;
    var hasFinanceStudy =
      /\b(?:economics|finance|banking|accounting|financial economics|economic governance)\b/i.test(
        String(rawText || "")
      );
    var hasAnalystLanguage =
      /\b(?:analysis|analyst|profitability|report(?:ing|s)?|database|dashboard|forecast|research|power bi|microstrategy|stata|salesforce)\b/i.test(
        String(rawText || "")
      );
    var hasDataRoleLanguage =
      /\b(?:data analyst|data science|data scientist|business intelligence|bi analyst|dashboard|sql|python|tableau|power bi)\b/i.test(
        String(rawText || "")
      );

    if (!(allEarlyCareer || currentLevel <= 3)) {
      return "";
    }
    if (analystSkillHits < 2 && !hasAnalystLanguage) {
      return "";
    }
    if ((families || []).indexOf("investment") !== -1)
      return "Investment Analyst";
    if ((families || []).indexOf("technology") !== -1 && hasDataRoleLanguage)
      return "Data Analyst";
    if ((families || []).indexOf("commercial") !== -1)
      return "Commercial Analyst";
    if ((families || []).indexOf("corporate_finance") !== -1)
      return "FP&A Analyst";
    if ((families || []).indexOf("treasury") !== -1) return "Treasury Analyst";
    if (
      (families || []).indexOf("accounting") !== -1 &&
      (hasFinanceStudy || analystSkillHits >= 3)
    )
      return "Financial Analyst";
    if (
      (families || []).indexOf("risk_compliance") !== -1 &&
      analystSkillHits >= 2
    )
      return "Risk Analyst";
    if ((families || []).indexOf("credit") !== -1) return "Credit Analyst";
    if (hasFinanceStudy) return "Analyst";
    return "";
  }

