  function inferIntentFromImpliedFollowUpContext(text, semantics, frame) {
    var clean = normalizeCareerIntentText(
      cleanMessageText(text || "")
    ).toLowerCase();
    var currentFollowUp = getSharedFollowUpState();
    var pendingIntent = cleanMessageText(currentFollowUp.pendingIntent || "");
    var recentIntent = cleanMessageText(
      currentFollowUp.lastAnsweredIntent || currentFollowUp.lastUserIntent || ""
    );
    var activeIntent =
      pendingIntent ||
      cleanMessageText(currentFollowUp.secondaryIntent || "") ||
      recentIntent;
    var shortReply = false;
    var hasComparativeMeaning = false;
    var hasDecisionPreference = false;
    var hasRecruiterMeaning = false;
    var hasCompanyMeaning = false;

    if (!clean || !semantics || !frame) {
      return "";
    }

    shortReply = clean.split(/\s+/).length <= 8 && clean.length <= 72;
    hasComparativeMeaning =
      meaningFrameHasModifier(frame, [
        "comparative",
        "balanced",
        "tentative",
        "dismissive",
      ]) ||
      meaningFrameHasTopic(frame, [
        "probability",
        "strengths_weaknesses",
        "reputation",
        "stability",
        "prestige",
        "culture",
        "security",
        "tradeoff",
        "decision_preference",
      ]);
    hasDecisionPreference =
      /(?:the safer one|the bigger one|the stronger one|the more stable one|the better brand|probably|leaning|both|either|not really|brand|platform|culture[-\s]?wise|stability[-\s]?wise|safer option|risk reward|title or platform|brand or comp)/i.test(
        clean
      );
    hasRecruiterMeaning =
      meaningFrameHasTopic(frame, [
        "recruiter",
        "recruiter_route",
        "recruiter_process",
        "network",
      ]) ||
      meaningFrameHasAction(frame, ["contact"]) ||
      /(?:recruiter|hr|hiring manager|referral|warm intro|direct|route in|entry point|atwasal|tawasol|twasol)/i.test(
        clean
      );
    hasCompanyMeaning =
      meaningFrameHasTopic(frame, [
        "company",
        "culture",
        "reputation",
        "stability",
        "prestige",
        "security",
      ]) ||
      /(?:company|firm|employer|brand|culture|stable|stability|safe|safer|risk|reputation|سمعة|استقرار|براند|اسم قوي|آمن|امان)/i.test(
        clean
      );

    if (
      !shortReply &&
      !hasComparativeMeaning &&
      !hasRecruiterMeaning &&
      !hasCompanyMeaning
    ) {
      return "";
    }

    if (
      /recruiter_networking|referral_request|role_call_request/.test(
        activeIntent
      ) &&
      hasRecruiterMeaning
    ) {
      return "recruiter_networking";
    }

    if (
      /company_research|company_details|company_investment_focus/.test(
        activeIntent
      ) &&
      (hasCompanyMeaning || hasComparativeMeaning)
    ) {
      return "company_research";
    }

    if (
      /offer_decision|career_tradeoff|career_direction|job_search_strategy/.test(
        activeIntent
      ) &&
      (hasComparativeMeaning || hasDecisionPreference)
    ) {
      return "offer_decision";
    }

    if (
      /role_help|matching_jobs|specific_vacancy_details|job_search_help|opportunity_search/.test(
        activeIntent
      ) &&
      (hasComparativeMeaning || hasDecisionPreference)
    ) {
      return "role_help";
    }

    if (!activeIntent && hasRecruiterMeaning && semantics.has_question) {
      return "recruiter_networking";
    }

    if (
      !activeIntent &&
      hasCompanyMeaning &&
      (semantics.has_question || hasComparativeMeaning)
    ) {
      return "company_research";
    }

    if (
      !activeIntent &&
      hasDecisionPreference &&
      (semantics.has_question ||
        meaningFrameHasTopic(frame, ["tradeoff", "decision_preference"]))
    ) {
      return "offer_decision";
    }

    return "";
  }

