  function getRecruiterQuestionTopic(text) {
    var clean = normalizeCareerIntentText(cleanMessageText(text || ""));
    var hasRecruiterAnchor;
    if (!clean) {
      return "";
    }
    hasRecruiterAnchor =
      /\b(?:recruiter|recruiters|recruitment|headhunter|headhunting|hiring manager|talent acquisition|talent partner|hr|human resources)\b/i.test(
        clean
      );
    if (sourceTextMentionsRecruiterProcessBreakdown(clean)) {
      return "process_breakdown";
    }
    if (sourceTextMentionsRecruiterComparisonQuestion(clean)) {
      return "comparison";
    }
    if (
      hasRecruiterAnchor &&
      sourceTextMentionsRecruiterOutreachQuestion(clean)
    ) {
      return "outreach";
    }
    if (
      hasRecruiterAnchor &&
      sourceTextMentionsRecruiterSelectionQuestion(clean)
    ) {
      return "selection";
    }
    if (
      hasRecruiterAnchor &&
      sourceTextMentionsRecruiterQualityQuestion(clean)
    ) {
      return "quality";
    }
    if (
      hasRecruiterAnchor &&
      sourceTextMentionsRecruiterCoverageQuestion(clean)
    ) {
      return "coverage";
    }
    if (
      hasRecruiterAnchor &&
      sourceTextMentionsRecruiterRelationshipQuestion(clean)
    ) {
      return "relationship";
    }
    if (
      sourceTextMentionsRecruiterDiscoveryQuestion(clean) ||
      sourceTextMentionsRecruiterConnectionRequest(clean)
    ) {
      return "discovery";
    }
    return "";
  }

