  function formatNaturalList(items) {
    var cleanItems = (items || [])
      .map(function (item) {
        return toDisplayText(item);
      })
      .filter(Boolean);
    if (!cleanItems.length) {
      return "";
    }
    if (cleanItems.length === 1) {
      return cleanItems[0];
    }
    if (cleanItems.length === 2) {
      return cleanItems[0] + " and " + cleanItems[1];
    }
    return (
      cleanItems.slice(0, -1).join(", ") +
      ", and " +
      cleanItems[cleanItems.length - 1]
    );
  }

  function formatFactList(items) {
    return formatNaturalList((items || []).slice(0, 3));
  }

  function maskRecruiterEmailForDisplay(email) {
    var clean = cleanMessageText(email || "");
    var parts;
    var local;
    var domain;
    var domainParts;
    var localPrefix;
    var localSuffix;
    var domainRoot;
    var domainExtension;
    if (!clean || clean.indexOf("@") === -1) {
      return "";
    }
    parts = clean.split("@");
    local = parts[0] || "";
    domain = parts[1] || "";
    if (!local || !domain) {
      return "";
    }
    domainParts = domain.split(".");
    if (!domainParts.length) {
      return "";
    }
    localPrefix = local.charAt(0);
    localSuffix = local.length > 1 ? local.charAt(local.length - 1) : "";
    domainRoot = domainParts[0] || "";
    domainExtension = domainParts[domainParts.length - 1] || "com";
    return (
      localPrefix +
      "****" +
      localSuffix +
      "@" +
      domainRoot +
      "." +
      domainExtension
    );
  }

  function maskRecruiterNameForDisplay(name) {
    var clean = cleanMessageText(name || "");
    var parts;
    var first;
    var lastInitial;
    if (!clean) {
      return "";
    }
    parts = clean.split(/\s+/).filter(Boolean);
    if (!parts.length) {
      return clean;
    }
    first = parts[0];
    lastInitial =
      parts.length > 1
        ? parts[parts.length - 1].charAt(0).toUpperCase() + "."
        : "";
    return [first, lastInitial].filter(Boolean).join(" ");
  }

  function getRecruiterInitials(name) {
    var parts = cleanMessageText(name || "")
      .split(/\s+/)
      .filter(Boolean);
    if (!parts.length) {
      return "R";
    }
    if (parts.length === 1) {
      return parts[0].slice(0, 2).toUpperCase();
    }
    return (
      parts[0].charAt(0) + parts[parts.length - 1].charAt(0)
    ).toUpperCase();
  }

