  function describeConversationFocus() {
    var safeTargetFunctions = (conversationFacts.targetFunctions || []).filter(
      function (item) {
        return (
          isPlausibleJobSearchRoleTarget(item) &&
          !isLocationOnlyRoleTarget(item)
        );
      }
    );
    var functionFocus = formatFactList(safeTargetFunctions);
    var seniorityFocus = formatFactList(
      conversationFacts.targetSeniority || []
    );
    var currentLocations = formatFactList(
      conversationFacts.targetLocations || []
    );
    var futureLocations = formatFactList(
      conversationFacts.futureTargetLocations || []
    );
    var rolePart = "";
    var locationPart = "";
    var futurePart = "";

    if (functionFocus && seniorityFocus) {
      rolePart = seniorityFocus + " " + functionFocus + " roles";
    } else if (seniorityFocus) {
      rolePart = seniorityFocus + " roles";
    } else if (functionFocus) {
      rolePart = functionFocus + " roles";
    }

    if (currentLocations) {
      locationPart =
        (conversationFacts.targetLocations || []).length > 1
          ? "across " + currentLocations
          : "in " + currentLocations;
    }

    if (futureLocations) {
      futurePart = "with " + futureLocations + " as a later market";
    }

    return [rolePart, locationPart, futurePart].filter(Boolean).join(" ");
  }

