    function applyLoggedInProfilePreferences(profilePreferences) {
      var normalized = normalizeLoggedInProfilePreferences(profilePreferences);
      var seededRoleHints = [];
      loggedInProfilePreferences = normalized;
      if (!normalized) {
        return;
      }
      if (normalized.idealRole) {
        seededRoleHints.push(normalized.idealRole);
      }
      if (normalized.roleInterest) {
        seededRoleHints.push(normalized.roleInterest);
      }
      conversationFacts.targetFunctions = sanitizeRoleTargetList(
        conversationFacts.targetFunctions.concat(normalized.targetRoles)
      );
      if (seededRoleHints.length) {
        conversationFacts.targetFunctions = sanitizeRoleTargetList(
          conversationFacts.targetFunctions.concat(seededRoleHints)
        );
      }
      conversationFacts.targetLocations = dedupeList(
        conversationFacts.targetLocations.concat(normalized.targetLocations)
      );
      conversationFacts.targetSectors = dedupeList(
        conversationFacts.targetSectors.concat(normalized.targetSectors)
      );
      conversationFacts.excludedTargetFunctions = sanitizeRoleTargetList(
        conversationFacts.excludedTargetFunctions.concat(
          normalized.excludedRoles
        )
      );
      conversationFacts.excludedTargetLocations = dedupeList(
        conversationFacts.excludedTargetLocations.concat(
          normalized.excludedLocations
        )
      );
      conversationFacts.excludedTargetSectors = dedupeList(
        conversationFacts.excludedTargetSectors.concat(
          normalized.excludedSectors
        )
      );
      if (conversationFacts.excludedTargetFunctions.length) {
        conversationFacts.targetFunctions =
          conversationFacts.targetFunctions.filter(function (item) {
            return (
              conversationFacts.excludedTargetFunctions.indexOf(item) === -1
            );
          });
      }
      if (conversationFacts.excludedTargetLocations.length) {
        conversationFacts.targetLocations =
          conversationFacts.targetLocations.filter(function (item) {
            return (
              conversationFacts.excludedTargetLocations.indexOf(item) === -1
            );
          });
      }
    }

    function hydrateLoggedInResumeContext(resumeContext) {
      var normalized = normalizeLoggedInResumeContext(resumeContext);
      loggedInResumeContext = normalized;
      if (!normalized || !normalized.hasCv || !normalized.cvText) {
        return;
      }
      capturedCvText = normalized.cvText;
      if (
        !workspaceState.fileName ||
        workspaceState.fileName === "No CV uploaded yet"
      ) {
        workspaceState.fileName =
          normalized.activeFileName ||
          (normalized.source === "upload"
            ? "Active saved resume"
            : "Active CV profile");
      }
      if (
        !workspaceState.cvStatus ||
        workspaceState.cvStatus === "Waiting for your CV"
      ) {
        workspaceState.cvStatus = "Saved CV ready";
      }
    }

    function hasLoggedInSavedCvSource() {
      return !!(
        getConfig().isLoggedIn &&
        loggedInResumeContext &&
        loggedInResumeContext.hasCv
      );
    }

    function hasHydratedLoggedInSavedCvText() {
      return !!cleanMessageText(
        capturedCvText ||
          (loggedInResumeContext && loggedInResumeContext.cvText) ||
          ""
      );
    }

    function ensureLoggedInSavedCvText() {
      if (!hasLoggedInSavedCvSource()) {
        return Promise.resolve(false);
      }
      if (
        !cleanMessageText(capturedCvText) &&
        loggedInResumeContext &&
        cleanMessageText(loggedInResumeContext.cvText)
      ) {
        capturedCvText = cleanMessageText(loggedInResumeContext.cvText);
      }
      if (cleanMessageText(capturedCvText)) {
        return Promise.resolve(true);
      }
      return syncLoggedInResumeContextWithActiveSource().then(function (
        loaded
      ) {
        if (
          !loaded &&
          loggedInResumeContext &&
          cleanMessageText(loggedInResumeContext.cvText)
        ) {
          capturedCvText = cleanMessageText(loggedInResumeContext.cvText);
          return true;
        }
        return !!cleanMessageText(
          capturedCvText ||
            (loggedInResumeContext && loggedInResumeContext.cvText) ||
            ""
        );
      });
    }

    function hasLoggedInSavedCv() {
      return hasLoggedInSavedCvSource();
    }

    function getLoggedInActiveCvLabel() {
      if (!loggedInResumeContext) {
        return "your saved CV";
      }
      return (
        loggedInResumeContext.activeFileName ||
        (loggedInResumeContext.source === "upload"
          ? "your active saved resume"
          : "your active CV profile")
      );
    }

    function hasPremiumMemberChatAccess() {
      return !!(isLoggedIn && hasPremiumAccess);
    }

    function getNormalizedPremiumDeliveryFrequency(value) {
      var cleanValue = cleanMessageText(value || "").toLowerCase();
      if (!cleanValue) {
        return "";
      }
      if (
        cleanValue === "instant" ||
        cleanValue === "daily" ||
        cleanValue === "weekly"
      ) {
        return cleanValue;
      }
      if (
        /moment|strong match|as soon as|right away|right when|instant|immediately/.test(
          cleanValue
        )
      ) {
        return "instant";
      }
      if (/daily|every day/.test(cleanValue)) {
        return "daily";
      }
      if (/weekly|every week/.test(cleanValue)) {
        return "weekly";
      }
      return "";
    }

    function getPremiumDeliveryFrequencySummary() {
      var frequency = getNormalizedPremiumDeliveryFrequency(
        jobSearchDeliveryFrequency || ""
      );
      if (frequency === "instant") {
        return "the moment I see a strong match";
      }
      if (frequency === "weekly") {
        return "weekly";
      }
      if (frequency === "daily") {
        return "daily";
      }
      return "as the shortlist evolves";
    }

    function getCurrentPremiumMemberOnboardingState() {
      var memory = normalizeApplyChatMemory(
        applyChatMemory || getEmptyApplyChatMemory()
      );
      return {
        completed: !!memory.premiumOnboardingCompleted,
        location: cleanMessageText(
          jobSearchPreferredLocation ||
            memory.preferredLocation ||
            (conversationFacts.targetLocations &&
              conversationFacts.targetLocations[0]) ||
            ""
        ),
        visa: cleanMessageText(
          jobSearchNeedsVisa ||
            memory.globalVisaStatus ||
            conversationFacts.workAuthorizationStatus ||
            ""
        ),
        frequency: getNormalizedPremiumDeliveryFrequency(
          jobSearchDeliveryFrequency || memory.deliveryFrequency || ""
        ),
        role: cleanMessageText(
          (conversationFacts.targetFunctions &&
            conversationFacts.targetFunctions[0]) ||
            ""
        ),
        sector: cleanMessageText(
          (conversationFacts.targetSectors &&
            conversationFacts.targetSectors[0]) ||
            ""
        ),
      };
    }

    function shouldShowPremiumMemberOnboarding() {
      return false;
    }

    function setMemberOnboardingFeedback(message) {
      if (!memberOnboardingFeedback) {
        return;
      }
      memberOnboardingFeedback.textContent = cleanMessageText(message || "");
      memberOnboardingFeedback.hidden = !cleanMessageText(message || "");
    }

    function setSelectedOnboardingButton(buttons, selectedValue) {
      var cleanValue = cleanMessageText(selectedValue || "").toLowerCase();
      Array.prototype.slice.call(buttons || []).forEach(function (button) {
        var buttonValue = cleanMessageText(
          button.getAttribute(
            "data-sffc-apply-chat-member-onboarding-location"
          ) ||
            button.getAttribute(
              "data-sffc-apply-chat-member-onboarding-visa"
            ) ||
            button.getAttribute(
              "data-sffc-apply-chat-member-onboarding-frequency"
            ) ||
            ""
        ).toLowerCase();
        button.classList.toggle(
          "is-selected",
          !!cleanValue && buttonValue === cleanValue
        );
        button.setAttribute(
          "aria-pressed",
          button.classList.contains("is-selected") ? "true" : "false"
        );
      });
    }

    function prefillPremiumMemberOnboarding() {
      var onboardingState = getCurrentPremiumMemberOnboardingState();
      if (memberOnboardingLocationOtherInput) {
        memberOnboardingLocationOtherInput.value = "";
      }
      if (memberOnboardingRoleInput) {
        memberOnboardingRoleInput.value = onboardingState.role;
      }
      if (memberOnboardingSectorInput) {
        memberOnboardingSectorInput.value = onboardingState.sector;
      }
      setSelectedOnboardingButton(
        memberOnboardingLocationButtons,
        onboardingState.location
      );
      if (
        onboardingState.location &&
        !Array.prototype.slice
          .call(memberOnboardingLocationButtons || [])
          .some(function (button) {
            return (
              cleanMessageText(
                button.getAttribute(
                  "data-sffc-apply-chat-member-onboarding-location"
                ) || ""
              ).toLowerCase() === onboardingState.location.toLowerCase()
            );
          }) &&
        memberOnboardingLocationOtherInput
      ) {
        memberOnboardingLocationOtherInput.value = onboardingState.location;
      }
      setSelectedOnboardingButton(
        memberOnboardingVisaButtons,
        onboardingState.visa
      );
      setSelectedOnboardingButton(
        memberOnboardingFrequencyButtons,
        onboardingState.frequency
      );
      setMemberOnboardingFeedback("");
    }

    function showPremiumMemberOnboarding() {
      return false;
    }

    function hidePremiumMemberOnboarding() {
      return;
    }

    function getSelectedOnboardingButtonValue(buttons, attributeName) {
      var selected = Array.prototype.slice
        .call(buttons || [])
        .find(function (button) {
          return button.classList.contains("is-selected");
        });
      return selected
        ? cleanMessageText(selected.getAttribute(attributeName) || "")
        : "";
    }

    function commitPremiumMemberOnboarding(values) {
      var memoryPayload;
      var selectedLocation = cleanMessageText(values.location || "");
      var selectedVisa = cleanMessageText(values.visa || "");
      var selectedFrequency = getNormalizedPremiumDeliveryFrequency(
        values.frequency || ""
      );
      var selectedRole = cleanMessageText(values.role || "");
      var selectedSector = cleanMessageText(values.sector || "");

      if (selectedLocation) {
        jobSearchPreferredLocation = selectedLocation;
        applyJobSearchLocationIntent({
          current: [selectedLocation],
          future: [],
          excluded: [],
        });
      }

      if (selectedVisa) {
        jobSearchNeedsVisa = selectedVisa;
        conversationFacts.workAuthorizationStatus = selectedVisa;
        if (selectedLocation) {
          conversationFacts.locationVisaRequirements =
            conversationFacts.locationVisaRequirements || {};
          conversationFacts.locationVisaRequirements[
            sanitizeKey(selectedLocation)
          ] = selectedVisa;
        }
      }

      if (selectedFrequency) {
        jobSearchDeliveryFrequency = selectedFrequency;
      }

      if (selectedRole) {
        conversationFacts.targetFunctions = sanitizeRoleTargetList(
          conversationFacts.targetFunctions.concat([selectedRole])
        );
      }

      if (selectedSector) {
        conversationFacts.targetSectors = dedupeList(
          conversationFacts.targetSectors.concat([selectedSector])
        );
      }

      memoryPayload = normalizeApplyChatMemory(
        Object.assign({}, applyChatMemory || getEmptyApplyChatMemory(), {
          hasHistory: true,
          preferredLocation: jobSearchPreferredLocation || selectedLocation,
          globalVisaStatus: jobSearchNeedsVisa || selectedVisa,
          deliveryFrequency: jobSearchDeliveryFrequency || selectedFrequency,
          targetFunctions: conversationFacts.targetFunctions || [],
          targetSectors: conversationFacts.targetSectors || [],
          premiumOnboardingCompleted: true,
          updatedAt: new Date().toISOString(),
        })
      );
      applyChatMemory = memoryPayload;
      queueApplyChatMemoryPersist();
    }

    function continueAfterPremiumMemberOnboarding() {
      var launchContext = pendingLaunchContext;
      var shouldOpenFilePicker = pendingLaunchOpenFilePicker;

      hidePremiumMemberOnboarding();

      if (launchContext) {
        pendingLaunchContext = null;
        pendingLaunchOpenFilePicker = shouldOpenFilePicker;
        routePendingLaunchContext(launchContext);
        return;
      }

      focusComposer(getLauncherPlaceholder());
      showInitialLauncher();
    }

    function queueApplyChatMemoryPersist() {
      if (applyChatMemorySaveTimer) {
        window.clearTimeout(applyChatMemorySaveTimer);
      }
      applyChatMemorySaveTimer = window.setTimeout(function () {
        applyChatMemorySaveTimer = 0;
        persistApplyChatMemory();
      }, 320);
    }

    function sanitizeKey(value) {
      return String(value || "")
        .toLowerCase()
        .replace(/[^a-z0-9_-]+/g, "");
    }

    if (homeLauncherLocationMenu) {
      homeLauncherLocationMenu.hidden = true;
    }

