    function tokenizeCvRoleTerms(text) {
      var stopWords = getCvRoleStopWords();
      return dedupeList(
        cleanMessageText(text || "")
          .toLowerCase()
          .split(/[^a-z0-9+#&]+/)
          .filter(function (word) {
            return word && word.length >= 3 && !stopWords[word];
          })
      );
    }

