    function getRoleEntryPreviewMatches() {
      var baseItems = filterMatchingRoles().slice(0, 18);
      var normalizedRoleTitle = cleanMessageText(roleTitle || "").toLowerCase();
      var normalizedRoleLocation = cleanMessageText(
        roleLocation || ""
      ).toLowerCase();
      var titleTerms = getMatchingRoleTitleTerms(roleTitle || "").slice(0, 8);
      var seniorityTerms = getMatchingRoleTitleTerms(roleTitle || "").filter(
        function (term) {
          return /(?:analyst|associate|manager|director|principal|vp|vice president|head|lead|senior|junior)/i.test(
            term
          );
        }
      );
      return baseItems
        .map(function (item) {
          var haystack = buildMatchingRoleHaystack(item);
          var score = 0;
          if (
            normalizedRoleLocation &&
            haystack.indexOf(normalizedRoleLocation) !== -1
          ) {
            score += 18;
          }
          titleTerms.forEach(function (term) {
            if (term && haystack.indexOf(term) !== -1) {
              score += 8;
            }
          });
          seniorityTerms.forEach(function (term) {
            if (term && haystack.indexOf(term) !== -1) {
              score += 10;
            }
          });
          if (
            normalizedRoleTitle &&
            cleanMessageText(item.title || "").toLowerCase() ===
              normalizedRoleTitle
          ) {
            score += 14;
          }
          return {
            item: item,
            score: score,
          };
        })
        .filter(function (entry) {
          return entry.score > 0;
        })
        .sort(function (left, right) {
          return right.score - left.score;
        })
        .slice(0, 3)
        .map(function (entry) {
          return entry.item;
        });
    }

