    function getInitialJobSearchRefinementStep() {
      if (jobSearchSeedContext && jobSearchPreferredLocation) {
        if (!hasResolvedJobSearchVisaContext()) {
          return askJobSearchVisaQuestion;
        }
        return askJobSearchAnythingMissed;
      }
      if (jobSearchSeedContext && jobSearchAdditionalTargets.length) {
        return askJobSearchLocationQuestion;
      }
      if (shouldUseLoggedInSeededJobSearchIntake()) {
        return startJobSearchFromKnownPreferences;
      }
      return askJobSearchSimilarRolesQuestion;
    }

    function hasLoggedInSeededJobSearchDirection() {
      if (!getConfig().isLoggedIn) {
        return false;
      }
      if (
        loggedInProfilePreferences &&
        (loggedInProfilePreferences.targetRoles.length ||
          loggedInProfilePreferences.targetSectors.length ||
          loggedInProfilePreferences.idealRole ||
          loggedInProfilePreferences.roleInterest)
      ) {
        return true;
      }
      if (
        applyChatMemory &&
        applyChatMemory.premiumOnboardingCompleted &&
        ((conversationFacts.targetFunctions &&
          conversationFacts.targetFunctions.length) ||
          (conversationFacts.targetSectors &&
            conversationFacts.targetSectors.length))
      ) {
        return true;
      }
      return false;
    }

    function shouldUseLoggedInSeededJobSearchIntake() {
      if (!hasLoggedInSeededJobSearchDirection()) {
        return false;
      }
      if (
        jobSearchSeedContext &&
        (jobSearchSeedContext.roleTarget || jobSearchSeedContext.location)
      ) {
        return false;
      }
      return true;
    }

    function doesReplyKeepCurrentJobSearchLane(value) {
      var clean = cleanMessageText(value || "");
      var lowered = normalizeCareerIntentText(clean).toLowerCase();
      var currentLabels = [];
      var profile = getSharedCvRoleMatchProfile();
      var recommendation = buildCvRoleRecommendationContext();
      var anchor = cleanMessageText(getJobSearchPrimaryRoleAnchor() || "");

      if (!clean || !lowered) {
        return false;
      }
      if (
        /(?:widen|broaden|different|else|other|shift|move into|move it|another lane|another role|another sector|something different|go wider|وسع|أوسع|مختلف)/i.test(
          lowered
        )
      ) {
        return false;
      }

      currentLabels = dedupeList(
        [
          anchor,
          cleanMessageText(recommendation.primary || ""),
          cleanMessageText((profile && profile.title) || ""),
        ].concat(
          getCvDisplayLaneLabels(
            profile,
            recommendation,
            applyChatSharedRuntime.buildCvRoleMatches() || []
          )
        )
      )
        .map(function (item) {
          return normalizeCareerIntentText(
            cleanMessageText(item || "")
          ).toLowerCase();
        })
        .filter(Boolean);

      return currentLabels.some(function (label) {
        return (
          label &&
          (lowered === label ||
            lowered.indexOf(label) !== -1 ||
            label.indexOf(lowered) !== -1)
        );
      });
    }

    function getLoggedInSeededJobSearchFollowUpStep() {
      if (!hasResolvedJobSearchLocationFocus()) {
        return askJobSearchLocationQuestion;
      }
      if (!hasResolvedJobSearchVisaContext()) {
        return askJobSearchVisaQuestion;
      }
      return askJobSearchAnythingMissed;
    }

