    function getUnresolvedVisaLocations() {
      var locations = getJobSearchLocationFilters(true);
      var globalStatus = cleanMessageText(
        jobSearchNeedsVisa || conversationFacts.workAuthorizationStatus || ""
      );
      if (!locations.length) {
        return [];
      }
      if (globalStatus) {
        return [];
      }
      return locations.filter(function (location) {
        return !getLocationVisaRequirement(location);
      });
    }

