    function applyJobSearchLocationIntent(intent) {
      var current = dedupeList((intent && intent.current) || []);
      var future = dedupeList((intent && intent.future) || []);
      var excluded = dedupeList((intent && intent.excluded) || []);

      if (excluded.length) {
        conversationFacts.excludedTargetLocations = dedupeList(
          conversationFacts.excludedTargetLocations.concat(excluded)
        );
        conversationFacts.targetLocations =
          conversationFacts.targetLocations.filter(function (item) {
            return excluded.indexOf(item) === -1;
          });
        conversationFacts.futureTargetLocations =
          conversationFacts.futureTargetLocations.filter(function (item) {
            return excluded.indexOf(item) === -1;
          });
        if (
          jobSearchPreferredLocation &&
          excluded.indexOf(jobSearchPreferredLocation) !== -1
        ) {
          jobSearchPreferredLocation =
            current[0] || conversationFacts.targetLocations[0] || "";
        }
      }

      if (future.length) {
        conversationFacts.futureTargetLocations = dedupeList(
          conversationFacts.futureTargetLocations.concat(future)
        );
      }

      if (current.length) {
        conversationFacts.targetLocations = dedupeList(
          conversationFacts.targetLocations.concat(current)
        );
        current.forEach(function (item) {
          var futureIndex =
            conversationFacts.futureTargetLocations.indexOf(item);
          if (futureIndex !== -1) {
            conversationFacts.futureTargetLocations.splice(futureIndex, 1);
          }
        });
        if (!jobSearchPreferredLocation) {
          jobSearchPreferredLocation = current[0];
        }
      }
      queueApplyChatMemoryPersist();
    }

