    function rankHomeLauncherSuggestions(query) {
      var clean = cleanMessageText(query || "");
      var lower = clean.toLowerCase();
      var roles = getHomeLauncherRoleOptions();
      var locations = getHomeLauncherLocationOptions();
      var patterns = getHomeLauncherQueryPatterns();
      var suggestions = [];
      var locationMention = extractPrimarySearchLocation(clean);
      var hasLocationPhrase = /\bin\s+[a-z]/i.test(clean);

      function pushSuggestion(text, score) {
        var normalized = cleanMessageText(text);
        if (!normalized) {
          return;
        }
        suggestions.push({
          text: normalized,
          score: score || 0,
        });
      }

      roles.forEach(function (role) {
        var roleLower = role.toLowerCase();
        if (!lower) {
          patterns.suffixes.forEach(function (suffix, suffixIndex) {
            pushSuggestion(role + suffix, 24 - suffixIndex);
          });
          return;
        }
        if (
          roleLower.indexOf(lower) !== -1 ||
          lower.indexOf(roleLower) !== -1
        ) {
          patterns.suffixes.forEach(function (suffix, suffixIndex) {
            pushSuggestion(role + suffix, 130 - suffixIndex);
          });
          if (!locationMention && !hasLocationPhrase) {
            locations.forEach(function (location, index) {
              pushSuggestion(role + " jobs in " + location, 112 - index);
              pushSuggestion(role + " roles in " + location, 102 - index);
              pushSuggestion(
                role + " opportunities in " + location,
                96 - index
              );
            });
          }
        }
      });

      patterns.prefixes.forEach(function (prefix, prefixIndex) {
        roles.slice(0, 40).forEach(function (role, roleIndex) {
          var baseRole = (prefix + role).trim();
          if (
            !lower ||
            baseRole.indexOf(lower) !== -1 ||
            lower.indexOf(baseRole) !== -1
          ) {
            patterns.suffixes.forEach(function (suffix, suffixIndex) {
              pushSuggestion(
                baseRole + suffix,
                92 - prefixIndex - roleIndex - suffixIndex
              );
            });
            if (!locationMention && !hasLocationPhrase && roleIndex < 16) {
              locations.slice(0, 8).forEach(function (location, locationIndex) {
                pushSuggestion(
                  baseRole + " jobs in " + location,
                  82 - prefixIndex - roleIndex - locationIndex
                );
              });
            }
          }
        });
      });

      if (lower) {
        locations.forEach(function (location, index) {
          var locationLower = location.toLowerCase();
          if (lower.indexOf(locationLower) !== -1) {
            roles.slice(0, 32).forEach(function (role, roleIndex) {
              pushSuggestion(role + " jobs in " + location, 100 - roleIndex);
              pushSuggestion(role + " roles in " + location, 90 - roleIndex);
              pushSuggestion(
                role + " opportunities in " + location,
                84 - roleIndex
              );
            });
          }
        });
      }

      if (lower) {
        patterns.sectorPhrases.forEach(function (sector, sectorIndex) {
          if (lower.indexOf(sector.toLowerCase()) !== -1) {
            roles.slice(0, 24).forEach(function (role, roleIndex) {
              pushSuggestion(
                role + " jobs in " + sector,
                88 - sectorIndex - roleIndex
              );
              if (!locationMention) {
                locations
                  .slice(0, 10)
                  .forEach(function (location, locationIndex) {
                    pushSuggestion(
                      role + " jobs in " + sector + " in " + location,
                      76 - sectorIndex - roleIndex - locationIndex
                    );
                  });
              }
            });
          }
        });
      }

      if (lower && !suggestions.length) {
        if (locationMention) {
          pushSuggestion(clean, 90);
        } else {
          locations.forEach(function (location, index) {
            pushSuggestion(clean + " in " + location, 70 - index);
          });
        }
      }

      if (lower) {
        roles.slice(0, 28).forEach(function (role, roleIndex) {
          patterns.modifiers.forEach(function (modifier, modifierIndex) {
            if (
              modifier &&
              (lower.indexOf(role.toLowerCase()) !== -1 ||
                role.toLowerCase().indexOf(lower) !== -1)
            ) {
              pushSuggestion(
                role + " jobs" + modifier,
                74 - roleIndex - modifierIndex
              );
            }
          });
          patterns.schedulePhrases.forEach(function (schedule, scheduleIndex) {
            if (
              lower.indexOf(role.toLowerCase()) !== -1 ||
              role.toLowerCase().indexOf(lower) !== -1
            ) {
              pushSuggestion(
                role + " " + schedule + " jobs",
                68 - roleIndex - scheduleIndex
              );
              if (!locationMention) {
                locations
                  .slice(0, 8)
                  .forEach(function (location, locationIndex) {
                    pushSuggestion(
                      role + " " + schedule + " jobs in " + location,
                      60 - roleIndex - scheduleIndex - locationIndex
                    );
                  });
              }
            }
          });
        });
      }

      return dedupeList(
        suggestions
          .sort(function (a, b) {
            return b.score - a.score;
          })
          .map(function (item) {
            return item.text;
          })
      ).slice(0, 24);
    }

    function closeHomeLauncherSuggestions() {
      homeLauncherSuggestionItems = [];
      homeLauncherSuggestionIndex = -1;
      if (homeLauncherSuggestions) {
        homeLauncherSuggestions.hidden = true;
        homeLauncherSuggestions.innerHTML = "";
      }
    }

    function applyHomeLauncherSuggestion(value, options) {
      var cleanValue = cleanMessageText(value || "");
      var shouldLaunch = !!(options && options.launch);
      if (!homeLauncherQuery || !cleanValue) {
        return;
      }
      homeLauncherQuery.value = cleanValue;
      closeHomeLauncherSuggestions();
      if (shouldLaunch) {
        pendingLaunchContext = buildActiveLauncherContext(cleanValue);
        pendingLaunchOpenFilePicker = false;
        openChat();
        return;
      }
      homeLauncherQuery.focus();
    }

    function renderHomeLauncherSuggestions(query) {
      var suggestions;
      if (!homeLauncherSuggestions || !homeLauncherQuery) {
        return;
      }
      suggestions = rankHomeLauncherSuggestions(query);
      if (!suggestions.length || !cleanMessageText(query || "")) {
        closeHomeLauncherSuggestions();
        return;
      }
      homeLauncherSuggestionItems = suggestions.slice(0);
      homeLauncherSuggestionIndex = -1;
      homeLauncherSuggestions.innerHTML = suggestions
        .map(function (item, index) {
          return (
            "" +
            '<button type="button" class="sffc-crm-apply-chat__home-suggestion" data-sffc-apply-chat-home-suggestion="' +
            escapeHtml(item) +
            '" data-sffc-apply-chat-home-suggestion-index="' +
            index +
            '">' +
            '<span class="sffc-crm-apply-chat__home-suggestion-icon" aria-hidden="true">⌕</span>' +
            '<span class="sffc-crm-apply-chat__home-suggestion-copy">' +
            escapeHtml(item) +
            "</span>" +
            "</button>"
          );
        })
        .join("");
      homeLauncherSuggestions.hidden = false;
    }

    function updateHomeLauncherSuggestionHighlight() {
      if (!homeLauncherSuggestions) {
        return;
      }
      homeLauncherSuggestions
        .querySelectorAll("[data-sffc-apply-chat-home-suggestion-index]")
        .forEach(function (button) {
          var index = parseInt(
            button.getAttribute("data-sffc-apply-chat-home-suggestion-index") ||
              "-1",
            10
          );
          button.classList.toggle(
            "is-active",
            index === homeLauncherSuggestionIndex
          );
        });
    }

