    function handoffToJobSearchMatches() {
      var emailPrompt = getJobSearchStartedMatchingLine();
      if (jobSearchMatchesReady) {
        updateWorkspace({
          visible: true,
        });
        askJobSearchPreferredEmail(false, emailPrompt);
        return;
      }
      jobSearchMatchesReady = true;
      jobSearchRolesReactionAsked = false;
      if (jobSearchRolesReactionTimer) {
        window.clearTimeout(jobSearchRolesReactionTimer);
        jobSearchRolesReactionTimer = 0;
      }
      setMonetizationState({
        shortlistShown: true,
      });
      updateWorkspace({
        visible: true,
      });
      askJobSearchPreferredEmail(false, emailPrompt);
    }

    function showInitialJobSearchMatchesThen(nextStep) {
      jobSearchMatchesReady = true;
      jobSearchRolesReactionAsked = false;
      if (jobSearchRolesReactionTimer) {
        window.clearTimeout(jobSearchRolesReactionTimer);
        jobSearchRolesReactionTimer = 0;
      }
      setMonetizationState({
        shortlistShown: true,
      });
      updateWorkspace({
        visible: true,
      });
      if (typeof nextStep === "function") {
        scheduleForCurrentUserTurn(nextStep, randomBetween(140, 260));
      }
    }

    function resetJobSearchContinuityState() {
      jobSearchContinuityState = null;
    }

    function ensureJobSearchContinuityState() {
      if (!jobSearchContinuityState) {
        jobSearchContinuityState = {
          topic: "priority_tradeoff",
          mode: applyMembershipCompleted ? "member" : "search",
          lastRoleDirection: "",
          lastSummary: "",
          askedTopics: [],
          browsing: false,
          lastConstraintType: "",
          lastQuestionType: "",
          unresolvedConcern: "",
        };
      }
      return jobSearchContinuityState;
    }

    function getJobSearchContinuityKnownTargets() {
      return sanitizeRoleTargetList(
        (conversationFacts.targetFunctions || [])
          .concat(conversationFacts.targetSectors || [])
          .concat(applyChatMemory.targetFunctions || [])
          .concat(applyChatMemory.targetSectors || [])
      ).slice(0, 4);
    }

    function getJobSearchContinuityKnownExclusions() {
      return dedupeList(
        (conversationFacts.excludedTargetFunctions || [])
          .concat(conversationFacts.excludedTargetSectors || [])
          .concat(applyChatMemory.excludedTargetFunctions || [])
          .concat(applyChatMemory.excludedTargetSectors || [])
      ).slice(0, 4);
    }

    function getJobSearchContinuitySavedRoleCount() {
      return dedupeList(
        (applyChatMemory.savedRoleTitles || []).concat(
          matchingCvConversationState &&
            matchingCvConversationState.savedRoleKeys
            ? getMatchingCvConversationRoleTitles(
                matchingCvConversationState.savedRoleKeys
              )
            : []
        )
      ).length;
    }

