    function getCoverLetterRoleFamilyConfig() {
      var registry = getCoverLetterTemplateRegistry();
      var profile = getCoverLetterRoleProfile();
      var familyConfig = registry[profile.family] || registry.general;
      var overlayBank = getCoverLetterOverlayBank();
      var overlayPhraseBank = getCoverLetterOverlayPhraseBank();
      var overlayThemes = overlayBank[profile.overlay] || [];
      var overlayPhrases = overlayPhraseBank[profile.overlay] || {};
      return {
        family: profile.family,
        overlay: profile.overlay,
        seniority: profile.seniority,
        strengthFallback: familyConfig.strengthFallback.slice(0),
        valueThemes: dedupeList(
          familyConfig.valueThemes.concat(overlayThemes)
        ).slice(0, 6),
        evidenceBridge: familyConfig.evidenceBridge.slice(0),
        evidenceLead: (overlayPhrases.evidenceLead || []).concat(
          (familyConfig.evidenceLead || registry.general.evidenceLead).slice(0)
        ),
        roleNeedPhrases: (overlayPhrases.roleNeedPhrases || []).concat(
          familyConfig.roleNeedPhrases.slice(0)
        ),
        openingWhy: (overlayPhrases.openingWhy || []).concat(
          familyConfig.openingWhy.slice(0)
        ),
        valueSentence: (overlayPhrases.valueSentence || []).concat(
          familyConfig.valueSentence.slice(0)
        ),
      };
    }

