    function normalizeCoverLetterTheme(text) {
      var clean = normalizeCoverLetterSignalLabel(text || "");
      if (!clean) {
        return "";
      }
      return clean
        .replace(/\bmarket research\b/gi, "market analysis")
        .replace(
          /\bkpi reporting and management reporting\b/gi,
          "KPI reporting and management reporting"
        )
        .replace(
          /\bperformance reporting and analytical reporting\b/gi,
          "performance reporting"
        )
        .replace(/\bgcc\b/gi, "GCC")
        .replace(/\bm&a\b/gi, "M&A")
        .replace(/\s+/g, " ")
        .trim();
    }

    function isWeakCoverLetterTheme(text) {
      var clean = normalizeCoverLetterTheme(text || "").toLowerCase();
      if (!clean) {
        return true;
      }
      return /^(?:excel|powerpoint|word|microsoft office|office skills|bachelor(?:'s|s)? degree|master(?:'s|s)? degree|degree|education|acca|cfa|cpa|aca|affiliate|candidate|university|college|leadership|responsiveness|judgement|execution responsibility)$/.test(
        clean
      );
    }

    function formatCoverLetterEmployerName() {
      var company = cleanMessageText(roleCompany || "");
      if (!company) {
        return "";
      }
      return company;
    }

    function getCoverLetterEmployerProfile() {
      var company = cleanMessageText(roleCompany || "");
      var brief = cleanMessageText(roleBriefText || "");
      var full = (company + " " + brief).toLowerCase();
      var profile = {
        archetype: "general",
        phrases: [],
      };

      if (
        /(sovereign wealth|swf|public investment fund|pif|adala|mubadala|gic|temasek)/i.test(
          full
        )
      ) {
        profile.archetype = "sovereign_wealth";
        profile.phrases = [
          "support long-horizon institutional investment decisions",
          "contribute in an environment where senior stakeholders expect clear reasoning and disciplined execution",
        ];
      } else if (
        /(family office|principal capital|uhnw|private office)/i.test(full)
      ) {
        profile.archetype = "family_office";
        profile.phrases = [
          "support principal capital with discretion, judgement, and dependable follow-through",
          "work in a setting where trust, multi-asset judgement, and careful execution all matter",
        ];
      } else if (
        /(bank|banking|credit suisse|jpmorgan|goldman|morgan stanley|barclays|hsbc|deutsche|citi|ubs)/i.test(
          full
        )
      ) {
        profile.archetype = "bank";
        profile.phrases = [
          "contribute in a high-standard banking environment where analytical quality and execution discipline are both important",
          "support decisions in an institution where responsiveness, precision, and judgement are expected",
        ];
      } else if (
        /(partners|capital|advisory|advisors|consulting|consultant|consultancy)/i.test(
          full
        )
      ) {
        profile.archetype = "advisory";
        profile.phrases = [
          "add value in a client-driven environment where judgement, communication, and execution quality all matter",
          "support work that depends on commercially grounded analysis and polished delivery",
        ];
      } else if (
        /(asset management|asset manager|portfolio management|fund management|investment management)/i.test(
          full
        )
      ) {
        profile.archetype = "asset_management";
        profile.phrases = [
          "support portfolio decisions with analysis that is both disciplined and decision-useful",
          "contribute in an investment environment where monitoring, reporting, and portfolio judgement are central",
        ];
      } else if (
        /(venture|startup|innovation|accelerator|incubator|product|technology|fintech)/i.test(
          full
        )
      ) {
        profile.archetype = "venture_product";
        profile.phrases = [
          "support decisions in an environment that values analytical clarity, curiosity, and practical execution",
          "contribute where market understanding and commercial problem-solving need to translate into action quickly",
        ];
      } else if (/(real estate|property|infrastructure|energy)/i.test(full)) {
        profile.archetype = "real_assets";
        profile.phrases = [
          "support investment decisions in a setting where underwriting discipline and commercial judgement are both essential",
          "contribute in an environment that depends on asset-level analysis and clear execution",
        ];
      }

      return profile;
    }

