    function normalizeCoverLetterThemeForProse(text) {
      var clean = normalizeCoverLetterTheme(text || "");
      if (!clean) {
        return "";
      }
      return clean
        .replace(
          /\bKPI reporting and management reporting\b/gi,
          "KPI and management reporting"
        )
        .replace(
          /\binvestment committee materials\b/gi,
          "investment committee materials"
        )
        .replace(/\bstakeholder reporting\b/gi, "stakeholder reporting")
        .replace(/\bvaluation support\b/gi, "valuation work")
        .replace(/\bdue diligence\b/gi, "due diligence")
        .replace(/\bportfolio construction\b/gi, "portfolio construction")
        .replace(/\bportfolio monitoring\b/gi, "portfolio monitoring")
        .trim();
    }

    function scoreCoverLetterTheme(label, analysis) {
      var clean = normalizeCoverLetterTheme(label);
      var lower;
      var score = 0;
      if (!clean) {
        return 0;
      }
      lower = clean.toLowerCase();
      if (
        ((analysis && analysis.confirmed_signals) || []).some(function (
          signal
        ) {
          return (
            normalizeCoverLetterTheme(getSignalLabel(signal)).toLowerCase() ===
            lower
          );
        })
      ) {
        score += 5;
      }
      if (
        ((analysis && analysis.adjacent_signals) || []).some(function (signal) {
          return (
            normalizeCoverLetterTheme(getSignalLabel(signal)).toLowerCase() ===
            lower
          );
        })
      ) {
        score += 2;
      }
      if (
        ((analysis && analysis.matched_keywords) || []).some(function (
          keyword
        ) {
          return normalizeCoverLetterTheme(keyword).toLowerCase() === lower;
        })
      ) {
        score += 3;
      }
      if (
        /(analysis|valuation|due diligence|portfolio|underwriting|reporting|research|investor|fundraising|governance|risk|markets)/i.test(
          clean
        )
      ) {
        score += 1;
      }
      return score;
    }

    function pickCoverLetterThemeLabels(analysis) {
      var confirmed = getStatementSafeConfirmedSignals(analysis);
      var adjacent = getAdjacentProofSignals(analysis);
      var matchedKeywords = ((analysis && analysis.matched_keywords) || [])
        .map(cleanMessageText)
        .filter(Boolean);
      var weighted = [];
      var seen = {};

      function pushWeighted(label, weight) {
        var clean = normalizeCoverLetterTheme(label);
        var key;
        if (!clean) {
          return;
        }
        if (isWeakCoverLetterTheme(clean)) {
          return;
        }
        key = clean.toLowerCase();
        seen[key] = (seen[key] || 0) + Number(weight || 0);
      }

      getSignalsByCategory(confirmed, [
        "hard_skill",
        "experience_background",
        "sector_exposure",
      ]).forEach(function (signal) {
        pushWeighted(getSignalLabel(signal), 4);
      });
      getSignalsByCategory(adjacent, [
        "hard_skill",
        "experience_background",
        "sector_exposure",
      ]).forEach(function (signal) {
        pushWeighted(getSignalLabel(signal), 2);
      });
      matchedKeywords.forEach(function (keyword) {
        pushWeighted(keyword, 3);
      });

      weighted = Object.keys(seen)
        .map(function (key) {
          return {
            label: key,
            weight: seen[key] + scoreCoverLetterTheme(key, analysis),
          };
        })
        .sort(function (a, b) {
          if (b.weight !== a.weight) {
            return b.weight - a.weight;
          }
          return a.label.length - b.label.length;
        })
        .map(function (item) {
          return normalizeCoverLetterTheme(item.label);
        });

      return dedupeList(weighted)
        .filter(function (label) {
          return !isWeakCoverLetterTheme(label);
        })
        .slice(0, 4);
    }

