    function getPromptAskCount(state) {
      var key = cleanMessageText(state || "");
      if (!key) {
        return 0;
      }
      return Number(promptAskCounts[key] || 0);
    }

    function registerPromptAsk(state) {
      var key = cleanMessageText(state || "");
      if (!key) {
        return 0;
      }
      if (!promptAskCounts[key]) {
        promptAskCounts[key] = 1;
      }
      return promptAskCounts[key];
    }

    function registerPromptRepeatAsk(state) {
      var key = cleanMessageText(state || "");
      if (!key) {
        return 0;
      }
      promptAskCounts[key] = Math.max(1, Number(promptAskCounts[key] || 1)) + 1;
      return promptAskCounts[key];
    }

    function clearPromptAskCount(state) {
      var key = cleanMessageText(state || "");
      if (!key) {
        return;
      }
      delete promptAskCounts[key];
    }

    function getPromptRecoveryLocationChoices() {
      var seed = [
        cleanMessageText(jobSearchPreferredLocation || ""),
        cleanMessageText(cvFacts.likelyCurrentLocation || ""),
        cleanMessageText(cvFacts.headerLocation || ""),
        extractPrimarySearchLocation(roleLocation || "") ||
          cleanMessageText(roleLocation || ""),
      ]
        .filter(Boolean)
        .join(" | ");
      return dedupeList(extractMentionedSearchLocations(seed)).slice(0, 3);
    }

