    function renderApplyIntroCvAnalysisHtml() {
      var facts = getJobSearchCvAnalysisFacts().slice(0, 4);
      var intro = isArabicChat()
        ? "حسناً. انتهيت من قراءة سيرتك."
        : "Okay. I've worked through your CV.";
      if (!facts.length) {
        return "<strong>" + escapeHtml(intro) + "</strong>";
      }
      return (
        "<strong>" +
        escapeHtml(intro) +
        "</strong><br><br><ul>" +
        facts
          .map(function (line) {
            return "<li>" + escapeHtml(line) + "</li>";
          })
          .join("") +
        "</ul>"
      );
    }

