    function askApplyIntroPreferredEmail() {
      var emailPrompt = isArabicChat()
        ? "ما البريد الذي تريدينني أن أستخدمه لرسالة الاختبار السريعة؟"
        : "Which email should I use for the quick test email?";

      function sendAndContinue(targetEmail) {
        var state = ensureApplyIntroState();
        clearResponseWatchdog();
        botMessageNow(getJobSearchEmailSendingLine());
        sendJobSearchMatchesEmail(targetEmail, {
          variant: "apply_intro",
          supportMode: state.supportMode || "",
          priority: state.priority || "",
          routeSummary: getApplyIntroRouteSummary(),
        })
          .then(function () {
            askApplyIntroInboxCheck();
          })
          .catch(function (error) {
            botMessage(
              getJobSearchEmailSendFailureLine(error && error.message),
              humanComposeDelay(
                cleanMessageText(
                  getJobSearchEmailSendFailureLine(error && error.message)
                ),
                1100,
                2000
              ),
              function () {
                focusComposer(isArabicChat() ? "اكتبي بريدك الإلكتروني" : "Type your email");
              }
            );
          });
      }

      botMessage(
        emailPrompt,
        humanComposeDelay(cleanMessageText(emailPrompt), 1000, 1800),
        function () {
          setPromptState(
            "apply_intro_collect_email",
            {
              other: function (value) {
                var analysed = analysePreferredEmail(value, "");
                if (!analysed) {
                  showPromptRecoveryMessage(
                    "apply_intro_collect_email",
                    getJobSearchFullEmailPromptLine(),
                    isArabicChat() ? "اكتبي بريدك الإلكتروني" : "Type your email",
                    value
                  );
                  return;
                }
                clearPromptState();
                echoPromptChoice(value);
                applyOnboardingPreferredEmail = analysed.raw;
                applyOnboardingEmailSuggestion = analysed.suggestion || "";
                ensureApplyIntroState().email =
                  analysed.suggestion || analysed.raw;
                window.setTimeout(function () {
                  var raw = applyOnboardingPreferredEmail;
                  var suggestion = applyOnboardingEmailSuggestion;
                  var confirmPrompt = getJobSearchEmailConfirmPrompt(
                    raw,
                    suggestion
                  );
                  botMessage(
                    confirmPrompt,
                    humanComposeDelay(cleanMessageText(confirmPrompt), 1200, 2200),
                    function () {
                      var confirmChoiceLabels = getBinaryChoiceLabels("clarify");
                      setPromptState(
                        "apply_intro_confirm_email",
                        {
                          yes: function (replyValue) {
                            echoPromptChoice(replyValue || suggestion || raw);
                            clearPromptState();
                            ensureApplyIntroState().email = suggestion || raw;
                            sendAndContinue(ensureApplyIntroState().email);
                          },
                          no: function (replyValue) {
                            echoPromptChoice(replyValue || getLocalizedDecisionLabel("no"));
                            clearPromptState();
                            askApplyIntroPreferredEmail();
                          },
                          other: function (replyValue) {
                            var decision = classifyEmailConfirmationReply(
                              replyValue,
                              raw,
                              suggestion
                            );
                            if (decision.intent === "change") {
                              clearPromptState();
                              echoPromptChoice(replyValue || getLocalizedDecisionLabel("no"));
                              askApplyIntroPreferredEmail();
                              return;
                            }
                            if (
                              decision.intent === "corrected" &&
                              decision.email
                            ) {
                              clearPromptState();
                              echoPromptChoice(replyValue);
                              ensureApplyIntroState().email = decision.email;
                              sendAndContinue(decision.email);
                              return;
                            }
                            if (decision.intent === "confirm") {
                              clearPromptState();
                              echoPromptChoice(replyValue);
                              ensureApplyIntroState().email =
                                decision.email || suggestion || raw;
                              sendAndContinue(ensureApplyIntroState().email);
                              return;
                            }
                            showPromptRecoveryMessage(
                              "apply_intro_confirm_email",
                              getJobSearchCorrectEmailPromptLine(),
                              isArabicChat()
                                ? "اكتبي البريد الصحيح"
                                : "Type the correct email",
                              replyValue
                            );
                          },
                        },
                        isArabicChat()
                          ? "أكدي البريد الصحيح"
                          : "Confirm the correct email"
                      );
                      focusComposer(
                        isArabicChat()
                          ? "أكدي البريد الصحيح"
                          : "Confirm the correct email"
                      );
                      addChoices(
                        [
                          {
                            label: suggestion || raw,
                            onClick: function () {
                              userMessage(suggestion || raw);
                              clearPromptState();
                              ensureApplyIntroState().email =
                                suggestion || raw;
                              sendAndContinue(ensureApplyIntroState().email);
                            },
                          },
                          {
                            label: isArabicChat()
                              ? "دعيني أصححه"
                              : confirmChoiceLabels.no,
                            onClick: function () {
                              userMessage(
                                isArabicChat()
                                  ? "دعيني أصححه"
                                  : confirmChoiceLabels.no
                              );
                              clearPromptState();
                              askApplyIntroPreferredEmail();
                            },
                          },
                        ],
                        "clarify"
                      );
                    }
                  );
                }, randomBetween(220, 420));
              },
            },
            isArabicChat() ? "اكتبي بريدك الإلكتروني" : "Type your email"
          );
          focusComposer(
            isArabicChat() ? "اكتبي بريدك الإلكتروني" : "Type your email"
          );
        }
      );
    }

