    function continueApplyIntroAfterCvUpload() {
      var previousState;
      if (jobSearchCvAcknowledged) {
        return;
      }
      jobSearchCvAcknowledged = true;
      previousState = ensureApplyIntroState();
      resetApplyIntroState();
      applyIntroState.homeEntry = !!previousState.homeEntry;
      applyIntroState.queryConfirmed = !!previousState.queryConfirmed;
      applyIntroState.desiredRole = previousState.desiredRole || "";
      applyIntroState.preferredSectors = previousState.preferredSectors || "";
      applyIntroState.preferredMarket = previousState.preferredMarket || "";
      applyIntroState.originalBrief = previousState.originalBrief || "";
      step = "apply_intro_questions";
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: "Preparing the application and intro route",
        note: "I'm using the CV and this role to decide whether the stronger route is tailored applications, direct intros, or both.",
        cvStatus: "Career assessment ready for this role",
        coverStatus: "Not started yet",
      });
      botMessage(
        renderApplyIntroCvAnalysisHtml(),
        humanComposeDelay(cleanMessageText(renderApplyIntroCvAnalysisHtml()), 1200, 2200),
        function () {
          if (ensureApplyIntroState().homeEntry) {
            if (
              ensureApplyIntroState().queryConfirmed &&
              ensureApplyIntroState().desiredRole
            ) {
              askApplyIntroHomeSectorQuestion();
              return;
            }
            askApplyIntroHomeRoleQuestion();
            return;
          }
          askApplyIntroHelpfulQuestion();
        }
      );
    }

    function continueApplyIntroFromSavedCv() {
      uploadButton.hidden = true;
      input.disabled = false;
      updateWorkspace({
        visible: getAutoWorkspaceVisibility(),
        stage: "Reading your CV for the application and intro route",
        note: "I'm using the active CV already saved on your account, so I can move straight into the route planning.",
        fileName: getLoggedInActiveCvLabel(),
        cvStatus: "Saved CV ready for route planning",
        coverStatus: "Not started yet",
        activeTab: "original",
      });
      if (
        loggedInResumeContext &&
        loggedInResumeContext.activeFileUrl &&
        loggedInResumeContext.activeFileType === "pdf"
      ) {
        setWorkspacePreviewFromPdfUrl(loggedInResumeContext.activeFileUrl);
      }
      botMessage(
        "I'll use " +
          escapeHtml(getLoggedInActiveCvLabel()) +
          " unless you want to replace it.",
        humanComposeDelay(
          "I'll use your saved CV unless you want to replace it.",
          1500,
          2800
        ),
        function () {
          ensureLoggedInSavedCvText()
            .then(function (ready) {
              if (!ready) {
                throw new Error(
                  "I could not load the saved CV from your account just now."
                );
              }
              return fetchCvAnalysis(capturedCvText)
                .then(function (analysis) {
                  mergeCvFacts(analysis || {});
                  return analysis || {};
                })
                .catch(function () {
                  return {};
                });
            })
            .then(function () {
              continueApplyIntroAfterCvUpload();
            })
            .catch(function () {
              botMessage(
                "I couldn't read the saved CV properly just now. If you want, upload a fresh copy and I'll use that instead.",
                humanComposeDelay(
                  "I couldn't read the saved CV properly just now.",
                  1800,
                  3600
                ),
                function () {
                  uploadButton.hidden = false;
                  focusComposer("Upload your CV or paste it here");
                }
              );
            });
        }
      );
    }

    function shouldBypassLoggedInJobSearchReplay(intentMode) {
      var cleanIntent = cleanMessageText(intentMode || "");
      if (!cleanIntent) {
        return false;
      }
      return cleanIntent !== "fresh_matches";
    }

