    function getLoggedInMemberDeskState() {
      var cacheKey = getLoggedInMemberDeskCacheKey();
      if (
        loggedInMemberDeskStateCache &&
        loggedInMemberDeskCacheKey === cacheKey
      ) {
        return loggedInMemberDeskStateCache;
      }
      var priority = getLoggedInMemberPrioritySnapshot();
      var follow = normalizeFollowUpState(
        (applyChatMemory && applyChatMemory.followUpState) ||
          followUpState ||
          {}
      );
      var recentTopics = dedupeList(
        (applyChatMemory && applyChatMemory.recentTopics) || []
      );
      var hasInterviewPressure =
        follow.pendingIntent === "interview_prep" ||
        follow.lastAnsweredIntent === "interview_prep" ||
        recentTopics.indexOf("interview_prep") !== -1 ||
        recentTopics.indexOf("interview_trouble") !== -1;
      var hasApplicationPressure =
        /application_follow_up|application_decision|apply_for_me/.test(
          follow.pendingIntent || ""
        ) ||
        recentTopics.indexOf("application_follow_up") !== -1 ||
        recentTopics.indexOf("application_strategy") !== -1;
      var hasStrategyPressure =
        priority.primaryConcern === "search_health" ||
        priority.primaryConcern === "stale_search" ||
        priority.primaryConcern === "stretch_heavy";
      var activity = getLoggedInMemberActivitySnapshot(
        priority,
        follow,
        recentTopics
      );
      loggedInMemberDeskCacheKey = cacheKey;
      loggedInMemberDeskStateCache = {
        priority: priority,
        follow: follow,
        hasInterviewPressure: hasInterviewPressure,
        hasApplicationPressure: hasApplicationPressure,
        hasStrategyPressure: hasStrategyPressure,
        activity: activity,
      };
      return loggedInMemberDeskStateCache;
    }

    function getLoggedInMemberActivitySnapshot(priority, follow, recentTopics) {
      var currentPriority = priority || getLoggedInMemberPrioritySnapshot();
      var currentFollow = normalizeFollowUpState(
        follow ||
          (applyChatMemory && applyChatMemory.followUpState) ||
          followUpState ||
          {}
      );
      var topics = Array.isArray(recentTopics)
        ? recentTopics
        : dedupeList((applyChatMemory && applyChatMemory.recentTopics) || []);
      var snapshot = currentPriority.snapshot || {};
      var focusSummary =
        summarizeSavedSearchFocus() ||
        cleanMessageText(snapshot.targetFunction || "your active search");
      var recruiterCount = Number(currentPriority.recruiterCount || 0);
      var strongCount = Number(
        (currentPriority.searchSummary &&
          currentPriority.searchSummary.strongCount) ||
          0
      );
      var stretchCount = Number(
        (currentPriority.searchSummary &&
          currentPriority.searchSummary.stretchCount) ||
          0
      );
      var savedCount = Number(currentPriority.savedRoleCount || 0);
      var pendingSummary = cleanMessageText(currentFollow.pendingSummary || "");
      var workAuth = cleanMessageText(snapshot.workAuthorization || "");
      var marketSignals = snapshot.marketSignals || {};
      var searchDeskLine = "";
      var applicationDeskLine = "";
      var recruiterDeskLine = "";
      var interviewDeskLine = "";
      var marketDeskLine = "";
      var statusLine = "";

      if (currentPriority.staleDays >= 30) {
        searchDeskLine =
          "The search desk needs a market refresh before I trust the older batch.";
      } else if (stretchCount > strongCount && stretchCount > 0) {
        searchDeskLine =
          "The search desk is still stretch-heavy, so route quality matters more than volume.";
      } else if (strongCount > 0) {
        searchDeskLine =
          "The search desk still has " +
          strongCount +
          " cleaner option" +
          (strongCount > 1 ? "s" : "") +
          " worth protecting.";
      } else {
        searchDeskLine =
          "The search desk needs a cleaner lane before I push more opportunities.";
      }

      if (pendingSummary) {
        applicationDeskLine =
          "Application desk pressure is sitting on " + pendingSummary + ".";
      } else if (savedCount > 0) {
        applicationDeskLine =
          "Application desk has " +
          savedCount +
          " saved role" +
          (savedCount > 1 ? "s" : "") +
          " still in the queue.";
      } else {
        applicationDeskLine =
          "Application desk is quiet enough that I can focus on route quality first.";
      }

      if (recruiterCount > 0) {
        recruiterDeskLine =
          "Access desk has " +
          recruiterCount +
          " recruiter or hiring-contact route" +
          (recruiterCount > 1 ? "s" : "") +
          " worth ranking.";
      } else {
        recruiterDeskLine =
          "Access desk is thin, so I should not pretend recruiter access is stronger than it is.";
      }

      if (
        topics.indexOf("interview_prep") !== -1 ||
        topics.indexOf("interview_trouble") !== -1
      ) {
        interviewDeskLine =
          "Interview desk pressure is already present, so fit-credibility answers need to be ready early.";
      } else {
        interviewDeskLine =
          "Interview desk is not urgent yet, but I would still prepare the market-logic answers before the pressure lands.";
      }

      if (cleanMessageText(marketSignals.fitWarning || "")) {
        marketDeskLine = cleanMessageText(marketSignals.fitWarning);
      } else if (workAuth === "needed") {
        marketDeskLine =
          "The market filter still needs to account for sponsorship and relocation friction.";
      } else if (snapshot.targetLocation) {
        marketDeskLine =
          "The market filter is centred on " +
          cleanMessageText(snapshot.targetLocation) +
          ", not a generic global search.";
      } else {
        marketDeskLine =
          "The market filter still needs a cleaner location anchor.";
      }

      statusLine = [
        "Search: " + searchDeskLine,
        "Applications: " + applicationDeskLine,
        "Access: " + recruiterDeskLine,
        "Market: " + marketDeskLine,
      ].join(" ");
      if (interviewDeskLine) {
        statusLine += " Interviews: " + interviewDeskLine;
      }

      return {
        focusSummary: focusSummary,
        searchDeskLine: searchDeskLine,
        applicationDeskLine: applicationDeskLine,
        recruiterDeskLine: recruiterDeskLine,
        interviewDeskLine: interviewDeskLine,
        marketDeskLine: marketDeskLine,
        statusLine: statusLine,
      };
    }

