    function detectPaymentFailureBucket(value) {
      var clean = cleanMessageText(value || "");
      var hasGenericPaymentFailure =
        /(payment (?:failed|fail|issue|problem|error|didn'?t go through|not going through)|checkout (?:issue|error|problem)|card (?:declined|failed|not working)|couldn'?t pay|couldnt pay|problem paying|issue paying|declined|error)/i.test(
          clean
        );

      if (!clean) {
        return { bucket: "", genericFailure: false };
      }
      if (
        /(insufficient[_\s-]?funds|balance_insufficient|insufficient credit|credit limit|available balance|not enough funds|insufficient balance|limit exceeded)/i.test(
          clean
        )
      ) {
        return { bucket: "insufficient_funds", genericFailure: true };
      }
      if (
        /(incorrect_cvc|invalid_cvc|incorrect_number|invalid_number|incorrect_zip|postal_code_invalid|invalid_expiry_month|invalid_expiry_year|incorrect address|incorrect_address|billing details|billing address|address missing|postal code|zip code|cvc check|cvv|card number is wrong|card details)/i.test(
          clean
        )
      ) {
        return { bucket: "invalid_details", genericFailure: true };
      }
      if (/(expired_card|expired card|card has expired)/i.test(clean)) {
        return { bucket: "expired_card", genericFailure: true };
      }
      if (
        /(authentication_required|payment_intent_action_required|payment_intent_authentication_failure|invoice_payment_intent_requires_action|3d secure|3ds|bank authentication|verify the payment|approval screen)/i.test(
          clean
        )
      ) {
        return { bucket: "authentication_required", genericFailure: true };
      }
      if (
        /(card_declined|payment_method_provider_decline|refer_to_customer|fraud prevention|fraud|suspicious activity|bank blocked|issuer declined|declined by bank|declined by issuer)/i.test(
          clean
        )
      ) {
        return { bucket: "bank_decline", genericFailure: true };
      }
      if (
        /(coupon_expired|promotion code|promo code|coupon|discount code)/i.test(
          clean
        )
      ) {
        return { bucket: "coupon_issue", genericFailure: true };
      }
      if (
        /(email_invalid|parameter_missing|parameter_invalid_empty|parameter_invalid_string_blank|parameter_invalid_string_empty|invalid email|missing fields|required field|please fix the errors above|password confirmation|doesn'?t match|doesnt match)/i.test(
          clean
        )
      ) {
        return { bucket: "form_issue", genericFailure: true };
      }
      if (
        /(processing_error|payment_method_provider_timeout|forwarding_api_upstream_connection_timeout|forwarding_api_upstream_connection_error|forwarding_api_upstream_error|lock_timeout|rate_limit|technical issue|timeout|timed out|try again later|processing error|something went wrong)/i.test(
          clean
        )
      ) {
        return { bucket: "technical_issue", genericFailure: true };
      }
      if (
        /(account_closed|account_error|account_invalid|bank_account_declined|bank_account_unusable|bank_account_verification_failed|payment_method_not_available|payment_method_unactivated|setup_attempt_failed|setup_intent_|payment_intent_|account limitations|daily spending limit|weekly spending limit)/i.test(
          clean
        )
      ) {
        return { bucket: "account_or_processor_issue", genericFailure: true };
      }
      if (hasGenericPaymentFailure) {
        return { bucket: "unknown_failure", genericFailure: true };
      }
      return { bucket: "", genericFailure: false };
    }

