    function requestCatchUpInvite(message, nextPlaceholder, resumePrompt) {
      var inviteMessage = cleanMessageText(message || lastUserInputText || "");
      var askCatchUpEmailPrompt = isArabicChat()
        ? "وش أفضل إيميل أرسل عليه الدعوة؟"
        : "What's the best email to send it to?";
      var askCatchUpFullEmailPrompt = isArabicChat()
        ? "أرسلي لي الإيميل الكامل اللي تبيني أستخدمه."
        : "Send me the full email address you'd want me to use.";
      var askCatchUpConfirmEmailPrompt = function () {
        return isArabicChat()
          ? "بس أتأكد، هل هو " + catchUpInviteEmail + "؟"
          : "Just double-checking — is that " + catchUpInviteEmail + "?";
      };
      var askCatchUpExactEmailPrompt = isArabicChat()
        ? "أرسلي لي الإيميل بالضبط اللي تبيني أستخدمه وأنا أكمل من هناك."
        : "Just send me the exact email you'd want me to use for the test email and I'll take it from there.";
      var askCatchUpNamePrompt = isArabicChat()
        ? "أكيد. قبل ما أرسلها، وش اسمك الكامل؟"
        : "Sure. Before I send it, what's your full name?";
      var askCatchUpClarifyNamePrompt = isArabicChat()
        ? "بس عشان أكتبه بشكل صحيح، أرسلي لي اسمك الكامل."
        : "Just so I get it right, send me your full name.";
      var catchUpInviteIntro = isArabicChat()
        ? "أكيد. أقدر أرسل لك دعوة catch-up ترجعك مباشرة إلى هنا."
        : "Yeah sure. I can send you a catch-up invite that links straight back here.";

      function finishCatchUpInvite() {
        sendCatchUpInviteRequest(
          catchUpInviteEmail,
          catchUpInviteFullName,
          inviteMessage
        )
          .then(function (data) {
            var reply =
              cleanMessageText((data && data.message) || "") ||
              (isArabicChat()
                ? "تم. أرسلت دعوة الـcatch-up وهي ترجعك مباشرة إلى هنا."
                : "Done. I've sent the catch-up invite through and it links straight back here.");
            botMessage(
              reply,
              humanComposeDelay(reply, 2000, 3800),
              function () {
                if (resumePrompt) {
                  botMessage(
                    resumePrompt,
                    humanComposeDelay(resumePrompt, 1800, 3600),
                    function () {
                      focusComposer(
                        nextPlaceholder || getComposerPlaceholder("message")
                      );
                    }
                  );
                  return;
                }
                focusComposer(
                  nextPlaceholder || getComposerPlaceholder("message")
                );
              }
            );
          })
          .catch(function (error) {
            var failReply =
              cleanMessageText(error && error.message) ||
              (isArabicChat()
                ? "ما قدرت أرسل دعوة الـcatch-up الآن. أرسلي لي أفضل إيميل مرة ثانية وأنا أعيد المحاولة."
                : "I couldn't send the catch-up invite just yet. Send me the best email again and I'll retry it.");
            botMessage(
              failReply,
              humanComposeDelay(failReply, 1800, 3600),
              function () {
                focusComposer(
                  isArabicChat() ? "اكتبي إيميلك" : "Type your email"
                );
              }
            );
          });
      }

      function askCatchUpEmail() {
        botMessage(
          askCatchUpEmailPrompt,
          humanComposeDelay(askCatchUpEmailPrompt, 1500, 3000),
          function () {
            setPromptState(
              "catch_up_collect_email",
              {
                other: function (value) {
                  var analysed = analysePreferredEmail(value, "");
                  if (!analysed) {
                    botMessage(
                      askCatchUpFullEmailPrompt,
                      humanComposeDelay(askCatchUpFullEmailPrompt, 1600, 3200),
                      function () {
                        focusComposer(
                          isArabicChat() ? "اكتبي إيميلك" : "Type your email"
                        );
                      },
                      humanReadDelay(value, 450)
                    );
                    return;
                  }
                  clearPromptState();
                  echoPromptChoice(value);
                  catchUpInviteEmail = analysed.confirmed || analysed.raw;
                  botMessage(
                    askCatchUpConfirmEmailPrompt(),
                    humanComposeDelay(
                      askCatchUpConfirmEmailPrompt(),
                      1800,
                      3400
                    ),
                    function () {
                      setPromptState(
                        "catch_up_confirm_email",
                        {
                          yes: function (replyValue) {
                            echoPromptChoice(
                              replyValue || (isArabicChat() ? "نعم" : "Yes")
                            );
                            finishCatchUpInvite();
                          },
                          no: function (replyValue) {
                            echoPromptChoice(
                              replyValue || (isArabicChat() ? "لا" : "No")
                            );
                            window.setTimeout(
                              askCatchUpEmail,
                              randomBetween(650, 1200)
                            );
                          },
                          other: function (replyValue) {
                            var clean = cleanMessageText(
                              replyValue || ""
                            ).toLowerCase();
                            var reAnalysed = analysePreferredEmail(
                              replyValue,
                              ""
                            );
                            if (reAnalysed && reAnalysed.confirmed) {
                              clearPromptState();
                              echoPromptChoice(replyValue);
                              catchUpInviteEmail = reAnalysed.confirmed;
                              finishCatchUpInvite();
                              return;
                            }
                            if (
                              /^(?:yes|yeah|yep|sure|ok|okay)$/i.test(clean) ||
                              /(correct|that one|yes that's right|yes thats right)/i.test(
                                clean
                              )
                            ) {
                              clearPromptState();
                              echoPromptChoice(replyValue);
                              finishCatchUpInvite();
                              return;
                            }
                            if (/^(?:no|nope|nah)$/i.test(clean)) {
                              clearPromptState();
                              echoPromptChoice(replyValue);
                              window.setTimeout(
                                askCatchUpEmail,
                                randomBetween(650, 1200)
                              );
                              return;
                            }
                            botMessage(
                              askCatchUpExactEmailPrompt,
                              humanComposeDelay(
                                askCatchUpExactEmailPrompt,
                                1700,
                                3400
                              ),
                              function () {
                                focusComposer(
                                  isArabicChat()
                                    ? "اكتبي إيميلك"
                                    : "Type your email"
                                );
                              },
                              humanReadDelay(replyValue, 450)
                            );
                          },
                        },
                        isArabicChat()
                          ? "أكدي الإيميل الصحيح"
                          : "Confirm the correct email"
                      );
                      focusComposer(
                        isArabicChat()
                          ? "أكدي الإيميل الصحيح"
                          : "Confirm the correct email"
                      );
                    }
                  );
                },
              },
              isArabicChat() ? "اكتبي إيميلك" : "Type your email"
            );
            focusComposer(isArabicChat() ? "اكتبي إيميلك" : "Type your email");
          }
        );
      }

      function askCatchUpName() {
        botMessage(
          askCatchUpNamePrompt,
          humanComposeDelay(askCatchUpNamePrompt, 1600, 3200),
          function () {
            setPromptState(
              "catch_up_collect_full_name",
              {
                other: function (value) {
                  if (!isReasonableFullName(value)) {
                    botMessage(
                      askCatchUpClarifyNamePrompt,
                      humanComposeDelay(
                        askCatchUpClarifyNamePrompt,
                        1600,
                        3200
                      ),
                      function () {
                        focusComposer(getFlowPlaceholder("full_name"));
                      },
                      humanReadDelay(value, 450)
                    );
                    return;
                  }
                  clearPromptState();
                  echoPromptChoice(value);
                  catchUpInviteFullName = cleanMessageText(value);
                  window.setTimeout(askCatchUpEmail, randomBetween(650, 1200));
                },
              },
              getFlowPlaceholder("full_name")
            );
            focusComposer(getFlowPlaceholder("full_name"));
          }
        );
      }

      botMessage(
        catchUpInviteIntro,
        humanComposeDelay(catchUpInviteIntro, 1800, 3600),
        function () {
          askCatchUpName();
        },
        humanReadDelay(inviteMessage, 450)
      );
    }

