    function handleReviewInterruption(value) {
      var intent = detectIntent(value);
      var reviewResumePrompt = pickVariant("review_resume_prompt", [
        "I'm still reading this through on my side, so you can keep sending things while I finish the pass.",
        "I'm still working through the CV here, but you can keep jumping in while I finish the first pass.",
        "I'm still in the middle of the review, so ask what you need and I'll keep this moving.",
      ]);

      function answerReviewInterruptionWithResume(sourceText, sourceIntent) {
        var answer = composeKnowledgeAnswer(sourceIntent, sourceText || value);
        if (!answer) {
          return false;
        }
        rememberAnsweredConversationIntent(sourceText || value, sourceIntent);
        runAfterCurrentThought(function () {
          botSequenceForCurrentTurn(
            [
              {
                html: answer,
                pause: humanReadDelay(sourceText || value, 450),
                delay: humanComposeDelay(answer, 2000, 4200),
              },
              {
                html: reviewResumePrompt,
                pause: humanReadDelay(answer, 360),
                delay: humanComposeDelay(reviewResumePrompt, 1700, 3400),
              },
            ],
            function () {
              focusComposer("You can jump in while I review");
            }
          );
        });
        return true;
      }

      if (intent === "identity") {
        handleIdentityQuestion("You can jump in while I review");
        return true;
      }

      if (intent === "request_real_person") {
        runAfterCurrentThought(function () {
          requestRealPersonJoin(
            value,
            "You can jump in while I review",
            "I'm still reviewing this side while that gets picked up."
          );
        });
        return true;
      }

      if (intent === "gratitude") {
        return answerReviewInterruptionWithResume(value, intent);
      }

      if (intent === "direct_apply") {
        runAfterCurrentThought(function () {
          botMessage(
            "I can send you the role link now if you prefer. I’ll still keep reading this side, but you do not need to wait for me.",
            humanComposeDelay(
              "I can send you the role link now if you prefer. I’ll still keep reading this side, but you do not need to wait for me.",
              2200,
              4800
            ),
            function () {
              offerDirectApply();
              focusComposer("You can jump in while I review");
            },
            humanReadDelay(value, 450)
          );
        });
        return true;
      }

      if (intent && intent !== "greeting" && intent !== "social_check") {
        if (answerReviewInterruptionWithResume(value, intent)) {
          return true;
        }
      }

      if (intent === "progress") {
        runAfterCurrentThought(function () {
          botMessage(
            pickVariant("review_progress_reply", [
              "Still reading it through. I'm on the recent experience and the role requirements now.",
              "Still with it. I'm checking the recent experience against the brief before I call anything out.",
              "Still looking. I just want to finish this first pass before I point you to the first fix.",
            ]),
            humanComposeDelay(
              "Still reading it through. I'm on the recent experience and the role requirements now.",
              2000,
              4200
            ),
            function () {
              focusComposer("You can jump in while I review");
            },
            humanReadDelay(value, 450)
          );
        });
        return true;
      }

      runAfterCurrentThought(function () {
        botMessage(
          pickVariant("review_generic_interrupt", [
            "I saw that. Let me finish this first pass and then I'll answer properly.",
            "Noted. I want to finish the quick read first, then I'll come back to that.",
            "I saw your message. Give me a minute to finish this pass, then I'll pick that up.",
          ]),
          humanComposeDelay(
            "I saw that. Let me finish this first pass and then I'll answer properly.",
            2000,
            4200
          ),
          function () {
            focusComposer("You can jump in while I review");
          },
          humanReadDelay(value, 450)
        );
      });
      return true;
    }

    function handleIdentityQuestion(nextStepPlaceholder) {
      botSequenceForCurrentTurn(
        [
          {
            html: pickVariant("identity_preface", [
              "Fair question.",
              "That's a fair question.",
              "Good question.",
            ]),
            delay: humanComposeDelay("Fair question.", 900, 1800),
            pause: humanReadDelay(lastUserInputText, 450),
          },
          {
            html: pickVariant("identity_answer", [
              "I'm Emily, the job search assistant here. I can help you sense-check the role, run a Career Assessment, and keep the next step practical.",
              "I'm the job search assistant here. My job is to help you assess the role, profile, LinkedIn positioning, and next application step.",
              "I'm Emily, the job search assistant in this chat. I can help you assess the role and show what would strengthen your candidate profile.",
            ]),
            delay: humanComposeDelay(
              "I'm Emily, the job search assistant here.",
              1700,
              5200
            ),
            pause: humanReadDelay("Fair question.", 400),
          },
        ],
        function () {
          focusComposer(nextStepPlaceholder);
        }
      );
    }

    function offerDirectApply() {
      var targetUrl = getApplicationTargetUrl(root);
      var roleLabel = getConcreteRoleEntryLabel();
      var introCopy = isArabicChat()
        ? "هذا هو رابط التقديم لهذا الدور. أستطيع أيضاً أن أريك جهة التوظيف المسؤولة عن هذا الدور وأرسل لك فرص مشابهة مع بيانات جهات التوظيف، حتى تزيدي فرصك!"
        : "Here's your application link for this role. I can also show you the recruiter behind this role and send you similar opportunities with recruiter contacts included, so you increase your chances!";

      function routeDirectApplyIntoTailoredFlow(value) {
        clearPromptState();
        if (value) {
          echoPromptChoice(value);
        }
        window.setTimeout(function () {
          startConsultantFlow("apply_for_me");
        }, randomBetween(650, 1200));
      }

      function routeDirectApplyIntoJobSearch(value) {
        clearPromptState();
        if (value) {
          echoPromptChoice(value);
        }
        window.setTimeout(function () {
          startConsultantFlow("job_search");
        }, randomBetween(650, 1200));
      }

      if (!isUsableExternalApplyUrl(targetUrl)) {
        botMessage(
          "I cannot see a working application link attached to this role from here. If you want, I can still help you tailor the CV and cover letter, or you can send me the correct application link.",
          humanComposeDelay(
            "I cannot see a working application link attached to this role from here. If you want, I can still help you tailor the CV and cover letter, or you can send me the correct application link.",
            2600,
            5600
          ),
          function () {
            focusComposer(getComposerPlaceholder("message"));
          },
          humanReadDelay(lastUserInputText, 600)
        );
        return;
      }

      botMessage(
        introCopy + buildApplyRouteHtml(root, { linkOnly: false }),
        humanComposeDelay(cleanMessageText(introCopy), 2400, 5000),
        function () {
          setPromptState(
            "direct_apply_cv_review_offer",
            {
              other: function (value) {
                var clean = cleanMessageText(value || "").toLowerCase();
                if (
                  /(career assessment|assessment|cv review|review my cv|check my cv|review my profile|linkedin|certification|credible case|help me with this role|advice|feedback|am i a fit|fit for this|cover letter|tailor my cv)/i.test(
                    clean
                  )
                ) {
                  routeDirectApplyIntoTailoredFlow(value);
                  return;
                }
                if (
                  /(find me a job|find more roles|similar roles|other roles|help me find a job|job search|any roles|what else is out there)/i.test(
                    clean
                  )
                ) {
                  routeDirectApplyIntoJobSearch(value);
                  return;
                }
                clearPromptState();
                focusComposer(getComposerPlaceholder("message"));
              },
            },
            getComposerPlaceholder("reply")
          );
          addChoices(
            [
              {
                label: "Find Recruiters Hiring",
                recommended: true,
                recommendedLabel: getLauncherRecommendedLabel(),
                onClick: function () {
                  userMessage("Find Recruiters Hiring");
                  routeDirectApplyIntoJobSearch("Find Recruiters Hiring");
                },
              },
            ],
            "launcher"
          );
          focusComposer(getComposerPlaceholder("reply"));
        },
        humanReadDelay(lastUserInputText, 600)
      );
    }

    function getApplyQualificationGap(analysis) {
      var gaps = (analysis && analysis.requirement_gaps) || [];
      return (
        gaps.find(function (gap) {
          return (
            gap &&
            gap.type === "qualification" &&
            String(gap.label || "").trim() !== "" &&
            !isClarificationGapResolved(gap)
          );
        }) || null
      );
    }

    function getApplyLanguageGap(analysis) {
      var gaps = (analysis && analysis.requirement_gaps) || [];
      return (
        gaps.find(function (gap) {
          return (
            gap &&
            gap.type === "language" &&
            String(gap.label || "").trim() !== "" &&
            !isClarificationGapResolved(gap)
          );
        }) || null
      );
    }

    function getApplyWorkAuthorizationGap(analysis) {
      var gaps = (analysis && analysis.requirement_gaps) || [];
      return (
        gaps.find(function (gap) {
          return (
            gap &&
            gap.type === "work_authorization" &&
            !isClarificationGapResolved(gap)
          );
        }) || null
      );
    }

    function getSignalLabel(signal) {
      return signal && signal.label ? String(signal.label).trim() : "";
    }

    function getSignalsByCategory(signals, categories) {
      var allowed = Array.isArray(categories) ? categories : [categories];
      return (signals || []).filter(function (signal) {
        return signal && allowed.indexOf(signal.category) !== -1;
      });
    }

    function getStatementSafeConfirmedSignals(analysis) {
      return ((analysis && analysis.confirmed_signals) || []).filter(function (
        signal
      ) {
        return (
          signal &&
          signal.safe_to_state_if_matched !== false &&
          signal.category !== "language" &&
          signal.category !== "credential" &&
          signal.category !== "soft_signal" &&
          signal.category !== "seniority_signal"
        );
      });
    }

    function getAdjacentProofSignals(analysis) {
      return ((analysis && analysis.adjacent_signals) || []).filter(function (
        signal
      ) {
        return (
          signal &&
          signal.category !== "language" &&
          signal.category !== "credential" &&
          signal.category !== "soft_signal" &&
          signal.category !== "seniority_signal"
        );
      });
    }

    function getConfirmationSignals(analysis) {
      return ((analysis && analysis.unconfirmed_signals) || []).filter(
        function (signal) {
          return signal && signal.needs_confirmation_if_unmatched;
        }
      );
    }

    function getRoleFamilyTone() {
      var clean = cleanMessageText(roleTitle).toLowerCase();
      if (
        /(analyst|associate|investment|private equity|venture|credit|underwrit|origination|research)/i.test(
          clean
        )
      ) {
        return "investing";
      }
      if (
        /(account|controller|fund accounting|reporting|finance manager|fp&a|treasury|audit)/i.test(
          clean
        )
      ) {
        return "reporting";
      }
      if (
        /(investor relations|business development|relationship|capital raising|fundraising|sales)/i.test(
          clean
        )
      ) {
        return "commercial";
      }
      if (
        /(risk|compliance|governance|operations|middle office|trade support)/i.test(
          clean
        )
      ) {
        return "risk_ops";
      }
      return "general";
    }

