    function setRecruiterOutreachBriefField(field, value) {
      recruiterOutreachBrief[field] = cleanMessageText(value || "");
      queueApplyChatMemoryPersist();
    }

    function getRecruiterOutreachBriefField(field) {
      return cleanMessageText((recruiterOutreachBrief || {})[field] || "");
    }

    function buildRecruiterOutreachBriefSummary() {
      var rows = [
        ["Target role", getRecruiterOutreachBriefField("role")],
        ["Seniority", getRecruiterOutreachBriefField("seniority")],
        ["Locations", getRecruiterOutreachBriefField("locations")],
        ["Sectors", getRecruiterOutreachBriefField("sectors")],
        ["Recruiter / firm targets", getRecruiterOutreachBriefField("targets")],
        ["Desired outcome", getRecruiterOutreachBriefField("outcome")],
      ];
      return rows
        .filter(function (row) {
          return !!row[1];
        })
        .map(function (row) {
          return row[0] + ": " + row[1];
        })
        .join("\n");
    }

    function answerRecruiterOutreachQuestion(question, resumeStep) {
      var reply = getRecruiterOutreachQuestionReply(question);
      botMessage(
        reply,
        humanComposeDelay(reply, 1700, 3600),
        function () {
          askRecruiterOutreachBriefQuestion(resumeStep);
        },
        humanReadDelay(question, 500)
      );
    }

    function getRecruiterOutreachQuestionReply(question) {
      var clean = cleanMessageText(question || "");
      var intent = detectIntent(clean);
      if (/why|what.*need|what.*for|purpose|how.*work/i.test(clean)) {
        return "I’m collecting this so the team can decide which recruiter lane is worth using, who to approach, and what outcome to push for. I’ll keep it tight.";
      }
      if (/cost|price|pay|membership|premium/i.test(clean)) {
        return "This is a premium outreach path. The brief helps the team avoid generic outreach and focus on the recruiters most likely to understand your profile.";
      }
      if (intent === "identity") {
        return "I’m Emily, the MENA Careers advisor. For this chat, I’m helping prepare a recruiter outreach brief for the team.";
      }
      return "Good question. I’ll keep the outreach focused on recruiter targeting and profile positioning, then we can tighten anything that is unclear.";
    }

    function askRecruiterOutreachBriefQuestion(part) {
      var currentPart = part || "role";
      var prompt;
      var placeholder;
      var nextPart;
      var field;
      var choices = [];

      if (currentPart === "role") {
        prompt = "Which role or role family should recruiter outreach focus on?";
        placeholder = "e.g. Investment Analyst, PE Associate";
        field = "role";
        nextPart = "seniority";
        choices = ["Investment Analyst", "Private Equity Associate", "Finance Manager"];
      } else if (currentPart === "seniority") {
        prompt = "What seniority should we position you for?";
        placeholder = "e.g. Analyst, Associate, Manager";
        field = "seniority";
        nextPart = "locations";
        choices = ["Analyst", "Associate", "Manager"];
      } else if (currentPart === "locations") {
        prompt = "Which locations should recruiters focus on?";
        placeholder = "e.g. Dubai, Abu Dhabi, Riyadh, London";
        field = "locations";
        nextPart = "sectors";
        choices = ["Dubai", "Abu Dhabi", "Riyadh"];
      } else if (currentPart === "sectors") {
        prompt = "Which sectors or asset classes matter most?";
        placeholder = "e.g. Private Equity, Real Estate, Asset Management";
        field = "sectors";
        nextPart = "targets";
        choices = ["Private Equity", "Investment Banking", "Asset Management"];
      } else if (currentPart === "targets") {
        prompt = "Any recruiter types, target firms, or firms to avoid?";
        placeholder = "Type target recruiters, firms, or anything to avoid";
        field = "targets";
        nextPart = "outcome";
      } else {
        prompt = "What outcome should the outreach push for?";
        placeholder = "e.g. recruiter calls, role introductions, market feedback";
        field = "outcome";
        nextPart = "submit";
        choices = ["Recruiter calls", "Role introductions", "Market feedback"];
      }

      botMessage(
        prompt,
        humanComposeDelay(prompt, 1400, 3000),
        function () {
          setPromptState(
            "recruiter_outreach_" + currentPart,
            {
              other: function (value) {
                setRecruiterOutreachBriefField(field, value);
                if (nextPart === "submit") {
                  submitRecruiterOutreachBrief();
                  return;
                }
                askRecruiterOutreachBriefQuestion(nextPart);
              },
              question: function (questionValue) {
                answerRecruiterOutreachQuestion(questionValue, currentPart);
              },
            },
            placeholder
          );
          focusComposer(placeholder);
          if (choices.length) {
            addChoices(
              choices.map(function (label) {
                return {
                  label: label,
                  onClick: function () {
                    userMessage(label);
                    promptReplyWasTyped = true;
                    clearPromptState();
                    setRecruiterOutreachBriefField(field, label);
                    if (nextPart === "submit") {
                      submitRecruiterOutreachBrief();
                      return;
                    }
                    askRecruiterOutreachBriefQuestion(nextPart);
                  },
                };
              }),
              "clarify"
            );
          }
        },
        humanReadDelay(lastUserInputText, 450)
      );
    }

    function submitRecruiterOutreachBrief() {
      var summary = buildRecruiterOutreachBriefSummary();
      var intro =
        "That gives the team enough to prepare the recruiter outreach brief.";
      var sending = "I’m sending this through with your Career Assessment now.";
      clearPromptState();
      step = "recruiter_outreach_submitting";
      botSequenceForCurrentTurn(
        [
          {
            html: intro,
            delay: humanComposeDelay(intro, 1200, 2600),
            pause: humanReadDelay(lastUserInputText, 450),
          },
          {
            html: sending,
            delay: humanComposeDelay(sending, 1200, 2600),
            pause: humanReadDelay(intro, 350),
          },
        ],
        function () {
          sendHumanHandoffRequest(
            "Recruiter outreach discovery brief\n\n" + summary,
            "recruiter_outreach_discovery"
          )
            .then(function () {
              var done =
                "Done. The recruiter outreach brief is with the team. If you want to add a recruiter, firm, or location, send it here and I’ll add it to the same brief.";
              step = "recruiter_outreach_submitted";
              botMessage(
                done,
                humanComposeDelay(done, 1700, 3600),
                function () {
                  focusComposer("Add anything else for recruiter outreach");
                },
                humanReadDelay(sending, 450)
              );
            })
            .catch(function () {
              var fallback =
                "I couldn’t send it through just now, but I’ve kept the brief in this chat. Send any extra recruiter context here and I’ll keep it together.";
              step = "recruiter_outreach_review_complete";
              botMessage(
                fallback,
                humanComposeDelay(fallback, 1700, 3600),
                function () {
                  focusComposer("Add anything else for recruiter outreach");
                },
                humanReadDelay(sending, 450)
              );
            });
        }
      );
    }

    function handleProfileReviewFollowUp(value) {
      var report;
      var reply = cleanMessageText(value || "");
      clearResponseWatchdog();
      if (!applyCvAnalysis && !capturedCvText) {
        promptForCv();
        return;
      }
      report = buildProfileReviewReport(applyCvAnalysis || pendingAnalysis || {});

      if (/score|fit|qualified|match|why/i.test(reply)) {
        botSequenceForCurrentTurn(
          [
            {
              html:
                "The current read is <strong>" +
                escapeHtml(report.scoreLabel) +
                "</strong> at " +
                escapeHtml(String(report.score)) +
                "/100.",
              pause: humanReadDelay(reply, 450),
              delay: humanComposeDelay(
                "The current read is " +
                  report.scoreLabel +
                  " at " +
                  report.score +
                  " out of 100.",
                1200,
                2600
              ),
            },
            {
              html:
                "That comes mainly from: " +
                escapeHtml(
                  report.strongEvidence.slice(0, 2).join(" ") ||
                    "the evidence already visible in your CV."
                ),
              pause: humanReadDelay(report.scoreLabel, 450),
              delay: humanComposeDelay(
                "That comes mainly from the evidence already visible in your CV.",
                1400,
                3000
              ),
            },
          ],
          function () {
            focusComposer("Ask what to improve first");
          }
        );
        return;
      }

      botSequenceForCurrentTurn(
        [
          {
            html:
              "I would start here: " +
              escapeHtml(
                report.suggestions[0] ||
                  "make the most relevant proof easier to find."
              ),
            pause: humanReadDelay(reply, 450),
            delay: humanComposeDelay(
              "I would start by making the most relevant proof easier to find.",
              1200,
              2600
            ),
          },
          {
            html:
              "Then I would check: " +
              escapeHtml(
                report.unclearEvidence[0] ||
                  "whether any key requirement still needs confirming."
              ),
            pause: humanReadDelay("I would start here.", 450),
            delay: humanComposeDelay(
              "Then I would check whether any key requirement still needs confirming.",
              1400,
              3000
            ),
          },
        ],
        function () {
                  focusComposer("Ask another Career Assessment question");
        }
      );
    }

    function fetchCvAnalysisFromFile(file, options) {
      var config = getConfig();
      var mode = options && options.mode === "fast" ? "fast" : "full";
      var critical = !(options && options.critical === false);
      var fileName = file && file.name ? String(file.name) : "resume";
      var targetRole = cleanMessageText(
        standaloneProfileReviewTargetRole ||
          (jobSearchSeedContext && jobSearchSeedContext.roleTarget) ||
          roleTitle ||
          ""
      );
      var formData = new FormData();
      if (!file) {
        return Promise.reject(new Error("Choose a CV file first."));
      }
      formData.append("action", "sffc_crm_apply_chat_analyze_cv");
      formData.append("nonce", config.nonce || "");
      formData.append("post_id", postId || root.getAttribute("data-post-id") || "");
      formData.append("jobs_post_id", jobsPostId || "");
      formData.append("analysis_mode", mode);
      formData.append("target_role", targetRole);
      formData.append("cv_file", file, fileName);

      if (critical) {
        beginApplyChatNetworkCritical();
      }
      return window
        .fetch(config.ajaxUrl || "/wp-admin/admin-ajax.php", {
          method: "POST",
          credentials: "same-origin",
          body: formData,
        })
        .then(parseAjaxJson)
        .then(function (payload) {
          if (!payload || !payload.success) {
            throw new Error(
              (payload && payload.data && payload.data.message) ||
                "Unable to analyse that CV."
            );
          }
          return payload.data || {};
        })
        .finally(function () {
          if (critical) {
            endApplyChatNetworkCritical();
          }
        });
    }

