    function askJobSearchPreferredEmail(skipPromptMessage, overridePrompt) {
      function continueAfterMatchesEmailSent() {
        window.setTimeout(askJobSearchInboxCheck, randomBetween(220, 420));
      }

      function handleMatchesEmailSendFailure(errorMessage) {
        var fallback = getJobSearchEmailSendFailureLine(errorMessage);
        botMessage(
          fallback,
          humanComposeDelay(fallback, 1100, 2000),
          function () {
            focusComposer(
              isArabicChat() ? "اكتبي بريدك الإلكتروني" : "Type your email"
            );
          }
        );
      }

      function sendMatchesAndContinue(targetEmail) {
        clearResponseWatchdog();
        botMessageNow(getJobSearchEmailSendingLine());
        sendJobSearchMatchesEmail(targetEmail)
          .then(function () {
            continueAfterMatchesEmailSent();
          })
          .catch(function (error) {
            handleMatchesEmailSendFailure(error && error.message);
          });
      }

      function openEmailPromptState() {
        var promptText = overridePrompt || getJobSearchEmailPrompt();
        setPromptState(
          "job_search_collect_preferred_email",
          {
            other: function (value) {
              var analysed = analysePreferredEmail(value, "");
              if (!analysed) {
                var fullEmailPrompt = getJobSearchFullEmailPromptLine();
                showPromptRecoveryMessage(
                  "job_search_collect_preferred_email",
                  fullEmailPrompt,
                  isArabicChat() ? "اكتبي بريدك الإلكتروني" : "Type your email",
                  value
                );
                return;
              }
              clearPromptState();
              echoPromptChoice(value);
              applyOnboardingPreferredEmail = analysed.raw;
              applyOnboardingEmailSuggestion = analysed.suggestion || "";
              window.setTimeout(function () {
                var raw = applyOnboardingPreferredEmail;
                var suggestion = applyOnboardingEmailSuggestion;
                var confirmPrompt = getJobSearchEmailConfirmPrompt(
                  raw,
                  suggestion
                );
                botMessage(
                  confirmPrompt,
                  humanComposeDelay(confirmPrompt, 1200, 2200),
                  function () {
                    setPromptState(
                      "job_search_confirm_email",
                      {
                        yes: function (replyValue) {
                          echoPromptChoice(replyValue || suggestion || raw);
                          applyOnboardingPreferredEmail = suggestion || raw;
                          applyOnboardingEmailSuggestion = "";
                          sendMatchesAndContinue(applyOnboardingPreferredEmail);
                        },
                        no: function (replyValue) {
                          echoPromptChoice(replyValue || "Let me correct it");
                          window.setTimeout(function () {
                            askJobSearchPreferredEmail(false);
                          }, randomBetween(220, 420));
                        },
                        other: function (replyValue) {
                          var emailDecision = classifyEmailConfirmationReply(
                            replyValue,
                            raw,
                            suggestion
                          );
                          if (emailDecision.intent === "change") {
                            clearPromptState();
                            echoPromptChoice(
                              replyValue || (isArabicChat() ? "لا" : "No")
                            );
                            window.setTimeout(function () {
                              askJobSearchPreferredEmail(false);
                            }, randomBetween(220, 420));
                            return;
                          }
                          if (
                            emailDecision.intent === "corrected" &&
                            emailDecision.email
                          ) {
                            clearPromptState();
                            echoPromptChoice(replyValue);
                            applyOnboardingPreferredEmail = emailDecision.email;
                            applyOnboardingEmailSuggestion = "";
                            sendMatchesAndContinue(
                              applyOnboardingPreferredEmail
                            );
                            return;
                          }
                          if (emailDecision.intent === "confirm") {
                            clearPromptState();
                            echoPromptChoice(replyValue);
                            applyOnboardingPreferredEmail =
                              emailDecision.email || suggestion || raw;
                            applyOnboardingEmailSuggestion = "";
                            sendMatchesAndContinue(
                              applyOnboardingPreferredEmail
                            );
                            return;
                          }
                          var correctEmailPrompt =
                            getJobSearchCorrectEmailPromptLine();
                          showPromptRecoveryMessage(
                            "job_search_confirm_email",
                            correctEmailPrompt,
                            isArabicChat()
                              ? "اكتبي البريد الصحيح"
                              : "Type the correct email",
                            replyValue
                          );
                        },
                      },
                      isArabicChat()
                        ? "أكدي البريد الصحيح"
                        : "Confirm the correct email"
                    );
                    focusComposer(
                      isArabicChat()
                        ? "أكدي البريد الصحيح"
                        : "Confirm the correct email"
                    );
                  }
                );
              }, randomBetween(220, 420));
            },
          },
          isArabicChat() ? "اكتبي بريدك الإلكتروني" : "Type your email"
        );
        focusComposer(
          isArabicChat() ? "اكتبي بريدك الإلكتروني" : "Type your email"
        );
      }

      if (skipPromptMessage) {
        openEmailPromptState();
        return;
      }

      var emailPrompt = overridePrompt || getJobSearchEmailPrompt();
      botMessage(
        emailPrompt,
        humanComposeDelay(emailPrompt, 1000, 1800),
        openEmailPromptState
      );
    }

