    function maybeHandleOffScriptInput(value) {
      var intent = detectIntent(value);

      if (maybeHandleLanguageSwitchRequest(value)) {
        return true;
      }
      if (
        looksLikeActualJobPostSearch(value, intent) &&
        !looksLikePastedCvText(value)
      ) {
        return searchActualJobPostsInChat(value);
      }

      function handleChoiceQuestion(copy) {
        botMessage(
          copy,
          humanComposeDelay(copy, 2000, 4600),
          function () {
            focusComposer(getFlowPlaceholder("what_to_check"));
          },
          humanReadDelay(lastUserInputText, 500)
        );
      }

      if (step === "choice") {
        if (intent === "social_check" || intent === "greeting") {
          handleWildcardSocialInput(
            intent,
            "Tell me how you'd like to proceed"
          );
          return true;
        }
        if (routeLauncherIntent(intent, value)) {
          return true;
        }
        if (
          (intent === "find_job" || intent === "job_search_help") &&
          searchActualJobPostsInChat(value)
        ) {
          return true;
        }
        if (answerRichOffScriptIntent(intent, value)) {
          return true;
        }
        if (
          answerKnowledgeQuestion(
            intent,
            "Tell me how you'd like to proceed",
            value
          )
        ) {
          return true;
        }
        if (intent === "identity") {
          handleIdentityQuestion("Choose an option or type a message");
          return true;
        }
        if (intent === "apply_for_me") {
          startConsultantFlow("apply_for_me");
          return true;
        }
        if (intent === "review_cv") {
          startConsultantFlow("review_profile");
          return true;
        }
        if (intent === "direct_apply") {
          offerDirectApply();
          return true;
        }
        if (intent === "different_question") {
          promptForDifferentQuestion();
          return true;
        }
        if (intent === "request_real_person") {
          requestRealPersonJoin(
            value,
            getLocalizedHumanHandoffPlaceholder(),
            "If you'd still like to keep going here while they pick that up, just tell me."
          );
          return true;
        }
        if (intent === "special_request") {
          handleChoiceQuestion(
            "I can help with that if it ties back to the application. If you want, tell me the question first, or send the CV and I'll check the role fit alongside it."
          );
          return true;
        }
        if (intent === "role_question") {
          handleChoiceQuestion(
            "Yes — ask me the question, or send the CV if you want me to judge it against the role while we talk it through."
          );
          return true;
        }
      }

      if (step === "upload" && intent === "identity") {
        handleIdentityQuestion("Upload CV or paste CV text");
        return true;
      }

      if (step === "job_search_upload") {
        if (answerJobSearchUploadSemantic(value, intent)) {
          return true;
        }
        if (intent === "social_check") {
          botSequenceForCurrentTurn(
            [
              {
                html: pickVariant("job_search_upload_social_reply", [
                  "I'm good, thanks for asking.",
                  "I'm doing well, thank you.",
                  "I'm good, thank you.",
                ]),
                pause: humanReadDelay(lastUserInputText, 450),
                delay: humanComposeDelay(
                  "I'm good, thanks for asking.",
                  1500,
                  3000
                ),
              },
              {
                html: getCvRequiredResumePrompt(),
                pause: humanReadDelay("I'm good, thanks for asking.", 420),
                delay: humanComposeDelay(
                  getCvRequiredResumePrompt(),
                  1800,
                  3600
                ),
              },
            ],
            function () {
              uploadButton.hidden = false;
              focusComposer("Upload your CV or paste it here");
            }
          );
          return true;
        }
        if (intent === "greeting") {
          botSequenceForCurrentTurn(
            [
              {
                html: pickVariant("job_search_upload_greeting_reply", [
                  "Hi there.",
                  "Hello.",
                  "Hi.",
                ]),
                pause: humanReadDelay(lastUserInputText, 450),
                delay: humanComposeDelay("Hi there.", 1200, 2600),
              },
              {
                html: getCvRequiredResumePrompt(),
                pause: humanReadDelay("Hi there.", 420),
                delay: humanComposeDelay(
                  getCvRequiredResumePrompt(),
                  1800,
                  3600
                ),
              },
            ],
            function () {
              uploadButton.hidden = false;
              focusComposer("Upload your CV or paste it here");
            }
          );
          return true;
        }
        if (answerRichOffScriptIntent(intent, value)) {
          return true;
        }
        if (intent === "request_real_person") {
          requestRealPersonJoin(
            value,
            "Upload your CV or paste it here",
            getCvRequiredResumePrompt()
          );
          return true;
        }
        if (
          answerKnowledgeQuestionWithResumePrompt(
            intent,
            "Upload your CV or paste it here",
            value
          )
        ) {
          return true;
        }
      }

      if (
        (step === "upload" ||
          step === "apply_upload" ||
          step === "job_search_upload" ||
          step === "consultant_confirm") &&
        (intent === "social_check" || intent === "greeting")
      ) {
        handleWildcardSocialInput(
          intent,
          input.placeholder || "Type your reply"
        );
        return true;
      }
      if (intent === "find_job" || intent === "job_search_help") {
        startConsultantFlow("job_search");
        return true;
      }
      if (answerRichOffScriptIntent(intent, value)) {
        return true;
      }
      if (intent === "request_real_person") {
        requestRealPersonJoin(
          value,
          input.placeholder || getComposerPlaceholder("message"),
          "If you'd still like to keep going here while they pick that up, just tell me."
        );
        return true;
      }
      if (
        answerKnowledgeQuestion(
          intent,
          input.placeholder || getComposerPlaceholder("message"),
          value
        )
      ) {
        return true;
      }

      return false;
    }

