        if (
          homeLauncherLocationMenu.hidden ||
          homeLauncherLocationMenu.contains(event.target) ||
          homeLauncherLocationToggle.contains(event.target)
        ) {
          return;
        }
        homeLauncherLocationMenu.hidden = true;
